-- ---------------------------------------------------------------------
-- sql_id: CHANGE-135 | module: PSSM | 类型: 查询
-- 文件: Server/PSSM/p_pssm_13060/mmlgap05_mon_inq.cpp | ledger_anchor: L79-L84 | 实际语句行: L79-L84
select substr(START_TIME,1,6) as MONTH,sum(OUT_STEEL_WT) AS CONS_PROD_WT FROM (select case START_TIME WHEN to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(START_TIME, 1, 8)when to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(START_TIME, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS START_TIME, OUT_STEEL_WT from TMMSM21 where FACTORY_DIV = 'A2') where START_TIME like '2025' || '%' group by substr(START_TIME, 1, 6);

-- ---------------------------------------------------------------------
-- sql_id: CHANGE-136 | module: PSSM | 类型: 查询
-- 文件: Server/PSSM/p_pssm_13060/mmlgap05_mon_inq.cpp | ledger_anchor: L98-L104 | 实际语句行: L98-L104
select substr(START_TIME, 1, 6) as MONTH, sum(SLAB_WT) AS SLAB_PROD_WT FROM(select case START_TIME WHEN to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(START_TIME, 1, 8) when to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(START_TIME, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS START_TIME, SLAB_WT from(select a.SLAB_WT, a.STATION_NO, a.START_TIME from TMMSM33 a, TMMSM31 b where a.HEAT_NO = b.HEAT_NO and a.FACTORY_DIV = 'A2')) where START_TIME like '2025' || '%' group by substr(START_TIME, 1, 6);

-- ---------------------------------------------------------------------
-- sql_id: CHANGE-142 | module: PSSM | 类型: 查询
-- 文件: Server/PSSM/p_pssm_13060/mmsmap05_inq.cpp | ledger_anchor: L108-L136 | 实际语句行: L108-L136
SELECT T1.STATION_NO,WT_YEAR,WT_MONTH,WT_WEEK,WT_DAY FROM(select STATION_NO,sum(OUT_STEEL_WT) AS WT_YEAR FROM (select case BLOW_START_TIME1 WHEN to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(BLOW_START_TIME1, 1, 8) when to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(BLOW_START_TIME1, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS BLOW_START_TIME1, OUT_STEEL_WT, case STATION_NO WHEN STATION_NO = 1 THEN '1#转炉钢水' when STATION_NO = 2 THEN '2#转炉钢水' when STATION_NO = 3 THEN '3#转炉钢水' end as STATION_NO from TMMSM21 where FACTORY_DIV = 'A1' and BLOW_START_TIME1 <> '') where BLOW_START_TIME1 like '2025' || '%' GROUP BY STATION_NO) T1 LEFT JOIN(select STATION_NO, sum(OUT_STEEL_WT) AS WT_MONTH FROM (select case BLOW_START_TIME1 WHEN to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(BLOW_START_TIME1, 1, 8)when to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING( BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(BLOW_START_TIME1, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS BLOW_START_TIME1, OUT_STEEL_WT, case STATION_NO WHEN STATION_NO = 1 THEN '1#转炉钢水' when STATION_NO = 2 THEN '2#转炉钢水' when STATION_NO = 3 THEN '3#转炉钢水' end as STATION_NO from TMMSM21 where FACTORY_DIV = 'A1' and BLOW_START_TIME1 <> '') where BLOW_START_TIME1 like '202501' || '%' GROUP BY STATION_NO)T2 ON T1.STATION_NO = T2.STATION_NO LEFT JOIN(select STATION_NO, sum(OUT_STEEL_WT) AS WT_WEEK FROM(select case BLOW_START_TIME1 WHEN to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(BLOW_START_TIME1, 1, 8)when to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING( BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS')THEN to_char(to_date(SUBSTRING(BLOW_START_TIME1, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS BLOW_START_TIME1, OUT_STEEL_WT, case STATION_NO WHEN STATION_NO = 1 THEN '1#转炉钢水' when STATION_NO = 2 THEN '2#转炉钢水' when STATION_NO = 3 THEN '3#转炉钢水' end as STATION_NO from TMMSM21 where FACTORY_DIV = 'A1' and BLOW_START_TIME1 <> '') where WEEK_ISO(to_date('20250101', 'YYYY-MM-DD')) = WEEK_ISO(to_date(BLOW_START_TIME1, 'YYYY-MM-DD')) GROUP BY STATION_NO)T3 ON T1.STATION_NO = T3.STATION_NO LEFT JOIN (select STATION_NO, sum(OUT_STEEL_WT) AS WT_DAY FROM(select case BLOW_START_TIME1 WHEN to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS') < to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(BLOW_START_TIME1, 1, 8) when to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(BLOW_START_TIME1, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS BLOW_START_TIME1, OUT_STEEL_WT, case STATION_NO WHEN STATION_NO = 1 THEN '1#转炉钢水' when STATION_NO = 2 THEN '2#转炉钢水' when STATION_NO = 3 THEN '3#转炉钢水' end as STATION_NO from TMMSM21 where FACTORY_DIV = 'A1' and BLOW_START_TIME1 <> '') where BLOW_START_TIME1 = '20250101' GROUP BY STATION_NO) T4 ON T1.STATION_NO = T4.STATION_NO;

