SELECT T1.STATION_NO,WT_YEAR,WT_MONTH,WT_WEEK,WT_DAY FROM(select STATION_NO,sum(FIN_LADLE_W_L) AS WT_YEAR FROM (select case START_TIME WHEN to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(START_TIME, 1, 8) when to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(START_TIME, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS START_TIME, FIN_LADLE_W_L, case STATION_NO WHEN STATION_NO = 1 THEN '1#LF产量' when STATION_NO = 2 THEN '2#LF产量' end as STATION_NO from TMMSM24 where FACTORY_DIV = 'A1' and START_TIME not in('')) where START_TIME like '2025' || '%' GROUP BY STATION_NO) T1 LEFT JOIN(select STATION_NO, sum(FIN_LADLE_W_L) AS WT_MONTH FROM (select case START_TIME WHEN to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(START_TIME, 1, 8)when to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING( START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(START_TIME, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS START_TIME, FIN_LADLE_W_L, case STATION_NO WHEN STATION_NO = 1 THEN '1#LF产量' when STATION_NO = 2 THEN '2#LF产量' end as STATION_NO from TMMSM24 where FACTORY_DIV = 'A1' and START_TIME not in('')) where START_TIME like '202501' || '%' GROUP BY STATION_NO)T2 ON T1.STATION_NO = T2.STATION_NO LEFT JOIN(select STATION_NO, sum(FIN_LADLE_W_L) AS WT_WEEK FROM(select case START_TIME WHEN to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(START_TIME, 1, 8)when to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING( START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS')THEN to_char(to_date(SUBSTRING(START_TIME, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS START_TIME, FIN_LADLE_W_L, case STATION_NO WHEN STATION_NO = 1 THEN '1#LF产量' when STATION_NO = 2 THEN '2#LF产量' end as STATION_NO from TMMSM24 where FACTORY_DIV = 'A1' and START_TIME not in('')) where WEEK_ISO(to_date('20250101', 'YYYY-MM-DD')) = WEEK_ISO(to_date(START_TIME, 'YYYY-MM-DD')) GROUP BY STATION_NO)T3 ON T1.STATION_NO = T3.STATION_NO LEFT JOIN (select STATION_NO, sum(FIN_LADLE_W_L) AS WT_DAY FROM(select case START_TIME WHEN to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') < to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(START_TIME, 1, 8) when to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(START_TIME, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS START_TIME, FIN_LADLE_W_L, case STATION_NO WHEN STATION_NO = 1 THEN '1#LF产量' when STATION_NO = 2 THEN '2#LF产量' end as STATION_NO from TMMSM24 where FACTORY_DIV = 'A1' and START_TIME not in('')) where START_TIME = '20250101' GROUP BY STATION_NO) T4 ON T1.STATION_NO = T4.STATION_NO;

