-- sql_id: CHANGE-145 | module: PSSM | 类型: 查询
-- 文件: Server/PSSM/p_pssm_13060/mmsmap05_inq.cpp | ledger_anchor: L304-L336 | 实际语句行: L304-L336
SELECT T1.STATION_NO,WT_YEAR,WT_MONTH,WT_WEEK,WT_DAY FROM(select STATION_NO,sum(SLAB_WT) AS WT_YEAR FROM (select case slab_cut_time WHEN to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(slab_cut_time, 1, 8) when to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING(slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(slab_cut_time, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS slab_cut_time, SLAB_WT, case STATION_NO WHEN STATION_NO = 1 THEN '1#连铸机板坯' WHEN STATION_NO = 2 THEN '2#连铸机板坯' WHEN STATION_NO = 3 THEN '3#连铸机板坯' WHEN STATION_NO = 4 THEN '4#连铸机板坯' end as STATION_NO from (select a.SLAB_WT, a.STATION_NO, a.slab_cut_time from TMMSM33 a where a.FACTORY_DIV = 'A1')) where slab_cut_time like '2025' || '%' GROUP BY STATION_NO) T1 LEFT JOIN(select STATION_NO, sum(SLAB_WT) AS WT_MONTH FROM (select case slab_cut_time WHEN to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(slab_cut_time, 1, 8) when to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING(slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(slab_cut_time, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS slab_cut_time, SLAB_WT, case STATION_NO WHEN STATION_NO = 1 THEN '1#连铸机板坯' WHEN STATION_NO = 2 THEN '2#连铸机板坯' WHEN STATION_NO = 3 THEN '3#连铸机板坯' WHEN STATION_NO = 4 THEN '4#连铸机板坯' end as STATION_NO from (select a.SLAB_WT, a.STATION_NO, a.slab_cut_time from TMMSM33 a where a.FACTORY_DIV = 'A1')) where slab_cut_time like '202501' || '%' GROUP BY STATION_NO)T2 ON T1.STATION_NO = T2.STATION_NO LEFT JOIN(select STATION_NO, sum(SLAB_WT) AS WT_WEEK FROM(select case slab_cut_time WHEN to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING (slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT( SUBSTRING(slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(slab_cut_time, 1, 8) when to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING(slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date( SUBSTRING(slab_cut_time, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS slab_cut_time, SLAB_WT, case STATION_NO WHEN STATION_NO = 1 THEN '1#连铸机板坯' WHEN STATION_NO = 2 THEN '2#连铸机板坯' WHEN STATION_NO = 3 THEN '3#连铸机板坯' WHEN STATION_NO = 4 THEN '4#连铸机板坯' end as STATION_NO from(select a.SLAB_WT, a.STATION_NO, a.slab_cut_time from TMMSM33 a where a.FACTORY_DIV = 'A1')) where WEEK_ISO(to_date('20250101', 'YYYY-MM-DD')) = WEEK_ISO(to_date(slab_cut_time, 'YYYY-MM-DD')) GROUP BY STATION_NO)T3 ON T1.STATION_NO = T3.STATION_NO LEFT JOIN(select STATION_NO, sum(SLAB_WT) AS WT_DAY FROM(select case slab_cut_time WHEN to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(slab_cut_time, 1, 8) when to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING(slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(slab_cut_time, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS slab_cut_time, SLAB_WT, case STATION_NO WHEN STATION_NO = 1 THEN '1#连铸机板坯' WHEN STATION_NO = 2 THEN '2#连铸机板坯' WHEN STATION_NO = 3 THEN '3#连铸机板坯' WHEN STATION_NO = 4 THEN '4#连铸机板坯' end as STATION_NO from(select a.SLAB_WT, a.STATION_NO, a.slab_cut_time from TMMSM33 a where a.FACTORY_DIV = 'A1')) where slab_cut_time = '20250101' GROUP BY STATION_NO) T4 ON T1.STATION_NO = T4.STATION_NO;

