-- sql_id: CHANGE-146 | module: PSSM | 类型: 查询
-- 文件: Server/PSSM/p_pssm_13060/mmsmap05_mon_inq.cpp | ledger_anchor: L83-L88 | 实际语句行: L83-L88
select substr(START_TIME,1,6) as MONTH,sum(OUT_STEEL_WT) AS CONS_PROD_WT FROM (select case START_TIME WHEN to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(START_TIME, 1, 8)when to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(START_TIME, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS START_TIME, OUT_STEEL_WT from TMMSM21 where FACTORY_DIV = 'A1') where START_TIME like '2025' || '%' group by substr(START_TIME, 1, 6);

-- ---------------------------------------------------------------------
-- sql_id: CHANGE-147 | module: PSSM | 类型: 查询
-- 文件: Server/PSSM/p_pssm_13060/mmsmap05_mon_inq.cpp | ledger_anchor: L102-L108 | 实际语句行: L102-L108
select substr(START_TIME, 1, 6) as MONTH, sum(SLAB_WT) AS SLAB_PROD_WT FROM(select case START_TIME WHEN to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(START_TIME, 1, 8) when to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(START_TIME, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS START_TIME, SLAB_WT from(select a.SLAB_WT, a.STATION_NO, a.START_TIME from TMMSM33 a, TMMSM31 b where a.HEAT_NO = b.HEAT_NO and a.FACTORY_DIV = 'A1')) where START_TIME like '2025' || '%' group by substr(START_TIME, 1, 6);

