-- sql_id: CHANGE-125 | module: PSSM | 类型: 查询
-- 文件: Server/PSSM/p_pssm_13050/pssm10cllcf2_inq.cpp | ledger_anchor: L191-L242 | 实际语句行: L244-L291
SELECT * FROM ( SELECT A.SLAB_DEST, A.CAST_LOT_NO || '-' || A.CAST_LOT_DIV_NO CAST_LOT_NO, B.CAST_NO, A.SLAB_THICK || '*' || A.SLAB_WIDTH MAT_SPECS, C.CAST_SUM, CASE WHEN D1.MAT_RCV IS NULL THEN 0 ELSE D1.MAT_RCV END || '/' || D.MAT_TUBE MAT_TUBE, A.CC_SEQ,A.RESTRAND_FLG,A.PONO,A.PONO_STATUS,A.ST_NO,A.SG_SIGN,A.PLAN_TAP_WT,A.HOT_SEND_FLAG,A.HOT_CHARGE_FLAG,A.PLAN_DATE,A.FACTORY_DIV,A.BACKLOG_EA FROM TPSSM10 A LEFT JOIN TPSSM11 B ON A.PONO = B.PONO LEFT JOIN (SELECT CAST_NO, COUNT(PONO) CAST_SUM FROM TPSSM11 WHERE CAST_NO <> ' ' GROUP BY CAST_NO) C ON B.CAST_NO = C.CAST_NO LEFT JOIN (SELECT PONO, COUNT(PONO) MAT_TUBE FROM TPSSM03 GROUP BY PONO) D ON A.PONO = D.PONO LEFT JOIN (SELECT PONO, COUNT(PONO) MAT_RCV FROM TPSSM03 WHERE SLAB_PROD_FLAG = '1' GROUP BY PONO) D1 ON A.PONO = D1.PONO WHERE 1=1 AND A.PONO_STATUS < 83 AND A.PONO_STATUS > 16 ORDER BY A.CC_SEQ,A.PLAN_DATE,A.CC_MACH_NO,B.CAST_NO,A.CAST_LOT_NO,A.CAST_LOT_DIV_NO) UNION ALL SELECT * FROM ( SELECT A.SLAB_DEST, A.CAST_LOT_NO || '-' || A.CAST_LOT_DIV_NO CAST_LOT_NO, B.CAST_NO, A.SLAB_THICK || '*' || A.SLAB_WIDTH MAT_SPECS, C.CAST_SUM, CASE WHEN D1.MAT_RCV IS NULL THEN 0 ELSE D1.MAT_RCV END || '/' || D.MAT_TUBE MAT_TUBE, A.CC_SEQ,A.RESTRAND_FLG,A.PONO,A.PONO_STATUS,A.ST_NO,A.SG_SIGN,A.PLAN_TAP_WT,A.HOT_SEND_FLAG,A.HOT_CHARGE_FLAG,A.PLAN_DATE,A.FACTORY_DIV,A.BACKLOG_EA FROM TPSSM10 A LEFT JOIN TPSSM11 B ON A.PONO = B.PONO LEFT JOIN (SELECT CAST_NO, COUNT(PONO) CAST_SUM FROM TPSSM11 WHERE CAST_NO <> ' ' GROUP BY CAST_NO) C ON B.CAST_NO = C.CAST_NO LEFT JOIN (SELECT PONO, COUNT(PONO) MAT_TUBE FROM TPSSM03 GROUP BY PONO) D ON A.PONO = D.PONO LEFT JOIN (SELECT PONO, COUNT(PONO) MAT_RCV FROM TPSSM03 WHERE SLAB_PROD_FLAG = '1' GROUP BY PONO) D1 ON A.PONO = D1.PONO WHERE 1=1 AND A.PONO_STATUS IN (15,16) AND A.CC_SEQ <> 999 ORDER BY A.CC_SEQ,A.PLAN_DATE,A.CC_MACH_NO,B.CAST_NO,A.CAST_LOT_NO,A.CAST_LOT_DIV_NO ) UNION ALL SELECT * FROM ( SELECT A.SLAB_DEST, A.CAST_LOT_NO || '-' || A.CAST_LOT_DIV_NO CAST_LOT_NO, B.CAST_NO, A.SLAB_THICK || '*' || A.SLAB_WIDTH MAT_SPECS, C.CAST_SUM, CASE WHEN D1.MAT_RCV IS NULL THEN 0 ELSE D1.MAT_RCV END || '/' || D.MAT_TUBE MAT_TUBE, A.CC_SEQ,A.RESTRAND_FLG,A.PONO,A.PONO_STATUS,A.ST_NO,A.SG_SIGN,A.PLAN_TAP_WT,A.HOT_SEND_FLAG,A.HOT_CHARGE_FLAG,A.PLAN_DATE,A.FACTORY_DIV,A.BACKLOG_EA FROM TPSSM10 A LEFT JOIN TPSSM11 B ON A.PONO = B.PONO LEFT JOIN (SELECT CAST_NO, COUNT(PONO) CAST_SUM FROM TPSSM11 WHERE CAST_NO <> ' ' GROUP BY CAST_NO) C ON B.CAST_NO = C.CAST_NO LEFT JOIN (SELECT PONO, COUNT(PONO) MAT_TUBE FROM TPSSM03 GROUP BY PONO) D ON A.PONO = D.PONO LEFT JOIN (SELECT PONO, COUNT(PONO) MAT_RCV FROM TPSSM03 WHERE SLAB_PROD_FLAG = '1' GROUP BY PONO) D1 ON A.PONO = D1.PONO WHERE 1=1 AND A.PONO_STATUS IN (15,16) AND A.CC_SEQ = 999 ORDER BY A.CC_SEQ,A.PLAN_DATE,A.CC_MACH_NO,B.CAST_NO,A.CAST_LOT_NO,A.CAST_LOT_DIV_NO );

-- ---------------------------------------------------------------------
-- sql_id: CHANGE-107 | module: WMSM | 类型: 查询
-- 文件: Server/WMSM/p_wmsm_8120/wmsmsmj3_rcm.cpp | ledger_anchor: L68-L68 | 实际语句行: L68-L68
select crane_no from twm06 where hall_no = decode('测试值', 'S00', hall_no, '测试值') and crane_no = CASE WHEN '测试值' IS NULL OR '测试值' = '' THEN crane_no ELSE '测试值' END order by crane_no;

