-- sql_id: CHANGE-103 | module: WMSM | 类型: 查询
-- 文件: Server/WMSM/p_wmsm_8140/wmsmrsl_inq.cpp | ledger_anchor: L77-L82 | 实际语句行: L77-L90
with mm1 as ( select decode(TRAN_TIME, ' ', TRAN_END_TIME, TRAN_TIME) TRAN_TIME, SUBSTR(decode(TRAN_TIME, ' ', TRAN_END_TIME, TRAN_TIME), 1, 8) tran_date, C_ISHOTSEND, MAT_ACT_WT from hMMSM01 where C_DIV = '2' and C_DELIVERY_STOCK = '6361'), mm2 as(select tran_date, sum(MAT_ACT_WT) RSL_DON from mm1 where 1 = 1 GROUP BY tran_date), mm3 as(select tran_date, sum(MAT_ACT_WT) RSL_NUM from mm1 where 1 = 1 AND C_ISHOTSEND = '1' GROUP BY tran_date) select A.tran_date, RSL_DON, RSL_NUM, CASE WHEN RSL_DON = 0 THEN 0 ELSE ROUND(RSL_NUM / RSL_DON, 3) END RSL_LV from mm2 a left join mm3 b on a.tran_date = B.tran_date where 1 = 1;

-- ---------------------------------------------------------------------
-- sql_id: CHANGE-106 | module: WMSM | 类型: 查询
-- 文件: Server/WMSM/p_wmsm_8140/wmsmsc_inq1.cpp | ledger_anchor: L85-L88 | 实际语句行: L85-L88
SELECT STRAND_NO, case when MAT_NO like '1A%' then SUBSTR(MAT_NO, 10) else SUBSTR(MAT_NO, 9) end MAT_NO, decode(MEND_FLAG,'1','X',' ')MEND_FLAG, round(MAT_LEN/1000,3) MAT_LEN, MAT_WT FROM VMMSM01 WHERE MAT_NO IN('测试值') ORDER BY STRAND_NO,MAT_NO;

-- ---------------------------------------------------------------------
-- sql_id: CHANGE-114 | module: TMSM | 类型: 查询
-- 文件: Server/TMSM/p_tmsm_7110/tmsm11av_inq.cpp | ledger_anchor: L80-L82 | 实际语句行: L80-L90
WITH TM11 AS (SELECT * FROM(SELECT row_number() over(partition by LADLE_NO ORDER BY RESUME_SEQ_NO desc) ROW_ID, A.* FROM(SELECT * FROM TTMSM11) A) WHERE ROW_ID = 1) SELECT CODE_DESC_1_CONTENT LADLE_NO, TM11.WORK_MAKER, TM11.ABN_REASON, tm11.DRYING_ST,TM11.DRYING_ET, TM11.BAKE_TYPE, TM11.BAKE_POS, TM11.UPLOAD_TIME, TM11.UPLOADER, TM11.MEMO_DETAIL, TM11.RESUME_SEQ_NO, TM11.LADLE_STATUS, case when TM11.LADLE_HEATING_DURATION = 0 and tm11.DRYING_ST != ' ' then CEIL((sysdate - TO_DATE(tm11.DRYING_ST, 'yyyy-mm-dd hh24-mi-ss')) * 24 ) else TM11.LADLE_HEATING_DURATION end LADLE_HEATING_DURATION, (select * from (select LADLE_LIFE from ttmsm12 where LADLE_NO = SUBSTR(TM11.LADLE_NO, 3, 2) and REC_CREATE_TIME > TM11.UPLOAD_TIME and C_DIV = 'A' order by TTMSM12.REC_CREATE_TIME desc) where ROWNUM = 1) LADLE_LIFE FROM TWMSMZD02 T1 LEFT JOIN TM11 ON T1.CODE_DESC_1_CONTENT = TM11.LADLE_NO WHERE CODE_CLASS = 'TM01' ORDER BY CODE_DESC_1_CONTENT;

