-- sql_id: CHANGE-95 | module: WMSM | 类型: 查询
-- 文件: Server/WMSM/p_wmsm_8110/wmsm01gg_inq1.cpp | ledger_anchor: L120-L151 | 实际语句行: L120-L158
select T03.CAST_LOT_NO, V1.ST_NO, (SELECT MAT_NO FROM VMMSM01 WHERE LSLAB_NO = T03.LSLAB_NO AND PONO = V1.PONO) MAT_NO, T03.*, '0' ifkepei, T33.LEN_MIN, T33.LEN_MAX, T33.MINWIDTH, T33.MAXWIDTH, T33.THICK_MIN, T33.THICK_MAX from VPSSM11 V1 left join(select LSLAB_NO, listagg(SLAB_NO, '/'), max(PONO) pono, max(SLAB_PROD_FLAG) SLAB_PROD_FLAG, decode(max(LSLAB_NO_LENGTH), 0, max(SLAB_LEN), max(LSLAB_NO_LENGTH)) SLAB_LEN, decode(max(LSLAB_NO_LENGTH_MAX), 0, max(SLAB_MAX_LEN), max(LSLAB_NO_LENGTH_MAX)) SLAB_MAX_LEN, decode(max(LSLAB_NO_LENGTH_MIN), 0, max(SLAB_MIN_LEN), max(LSLAB_NO_LENGTH_MIN)) SLAB_MIN_LEN, max(SLAB_WIDTH) SLAB_WIDTH, max(SLAB_THICK) SLAB_THICK, max(SLAB_DEST) SLAB_DEST, max(apn) apn, max(ORDER_NO) ORDER_NO, max(SG_SIGN) SG_SIGN, max(BILLET_TYPE) BILLET_TYPE, max(MATIRAL_CODE) MATIRAL_CODE, max(CAST_LOT_NO) CAST_LOT_NO, max(FACTORY_NEXT) FACTORY_NEXT from tpssm03 where PONO = '测试值' group by LSLAB_NO) T03 ON V1.PONO = T03.PONO left join Vpssm10 T10 ON V1.PONO = T10.PONO LEFT JOIN TMMSM33BPGG T33 ON DECODE(T10.SLAB_DEST, '41', '6', T10.C_DIV) = T33.ST_NO AND DECODE(SUBSTR(T03.MATIRAL_CODE, 2, 2), 'AA', 'J', 'AB', 'Z') = T33.SLAB_TYPE WHERE 1 = 1 and V1.PONO = '测试值';

-- ---------------------------------------------------------------------
-- sql_id: CHANGE-96 | module: WMSM | 类型: 查询
-- 文件: Server/WMSM/p_wmsm_8110/wmsm01gg_inq1.cpp | ledger_anchor: L204-L205 | 实际语句行: L204-L235
select T03.CAST_LOT_NO, V1.ST_NO,(SELECT MAT_NO FROM VMMSM01 WHERE LSLAB_NO=T03.LSLAB_NO AND PONO IN (SELECT PONO FROM TPSSM01 WHERE CAST_LOT_NO = '测试值')) MAT_NO, T03.*,'0'ifkepei,T33.LEN_MIN,T33.LEN_MAX,T33.MINWIDTH,T33.MAXWIDTH,T33.THICK_MIN,T33.THICK_MAX from VPSSM11 V1 left join (select LSLAB_NO, listagg(SLAB_NO, '/'), max(PONO) pono, max(SLAB_PROD_FLAG) SLAB_PROD_FLAG, decode(max(LSLAB_NO_LENGTH), 0, max(SLAB_LEN), max(LSLAB_NO_LENGTH)) SLAB_LEN, decode(max(LSLAB_NO_LENGTH_MAX), 0, max(SLAB_MAX_LEN), max(LSLAB_NO_LENGTH_MAX)) SLAB_MAX_LEN, decode(max(LSLAB_NO_LENGTH_MIN), 0, max(SLAB_MIN_LEN), max(LSLAB_NO_LENGTH_MIN)) SLAB_MIN_LEN, max(SLAB_WIDTH) SLAB_WIDTH, max(SLAB_THICK) SLAB_THICK, max(SLAB_DEST) SLAB_DEST, max(apn) apn, max(ORDER_NO) ORDER_NO, max(SG_SIGN) SG_SIGN, max(BILLET_TYPE) BILLET_TYPE, max(MATIRAL_CODE) MATIRAL_CODE, max(CAST_LOT_NO) CAST_LOT_NO, max(FACTORY_NEXT) FACTORY_NEXT from tpssm03 where CAST_LOT_NO = '测试值' group by LSLAB_NO) T03 ON V1.PONO = T03.PONO left join Vpssm10 T10 ON V1.PONO = T10.PONO LEFT JOIN TMMSM33BPGG T33 ON DECODE(T10.SLAB_DEST, '41', '6', T10.C_DIV) = T33.ST_NO AND DECODE(SUBSTR(T03.MATIRAL_CODE, 2, 2), 'AA', 'J', 'AB', 'Z') = T33.SLAB_TYPE WHERE 1 = 1 and V1.PONO IN (SELECT PONO FROM TPSSM01 WHERE CAST_LOT_NO = '测试值');

