-- 文件: Server/WMSM/p_wmsm_8110/wmsmsm11_inq.cpp | ledger_anchor: L167-L190 | 实际语句行: L167-L190
select twma0.MAT_NO, TWMA0.STOCK_OPER_ORDER SERV_TYPE, TWMA0.STOCK_OPER_ORDER, twma1.LGORT, twm41.C_BATCHID BATCH, twm41.C_DELIVERYID, twm41.C_SENDDEPT, twm41.C_SENDSTOCK, TWM41.C_ACCEPTSTOCK, CASE WHEN twm62.MAT_NO IS NULL THEN ' ' ELSE '1' END IF_LOGI, twm62.PRACTICE_NO, twm62.TRUCK_NO, nvl(TWM41.I_RESERVECOL3, twma1.MAT_LEN) MAT_LEN, nvl(TWM41.DELIVERY_WIDTH, twma1.MAT_WIDTH) MAT_WIDTH, nvl(TWM41.DELIVERY_THICKNESS, twma1.MAT_THICK) MAT_THICK, nvl(TWM41.N_SENDAMOUNT, twma1.MAT_WT) MAT_WT from twma0 left join vmmsm01 twma1 ON TWMA0.MAT_NO = TWMA1.MAT_NO left join twmSM62 TWM62 ON TWMA0.MAT_NO = TWM62.MAT_NO AND TWM62.UNLOAD_FLAG = '0' AND TWM62.DEAL_FLAG='I' left join twm41dj TWM41 ON TWMA0.MAT_NO = TWM41.C_BATCHUNIT AND TWM41.C_STATESIGN = '1' WHERE TWMA0.PROC_STATUS = '0' AND TWMA0.MAT_NO != ' ' AND TWMA0.STOCK_OPER_ORDER LIKE '1%' AND TWMA0.STOCK_OPER_ORDER NOT IN('1B');

