with mm1 as (select t1.HEAT_NO, t3.SG_GRADE_1, MAX(t1.MAT_WIDTH) MAT_WIDTH, MAX(t1.MAT_THICK) MAT_THICK, t1.ST_NO, SUM(T1.MAT_WT) MAT_WT, SUM(T1.MAT_LEN) MAT_LEN, MAX(T1.TRUCK_NO) TRUCK_NO, MAX(SUBSTR(T1.SLAB_NO, 18)) SLAB_NO from vmmsm01 t1 left join tqmts0x t3 on t1.ST_NO = t3.ST_NO where t1.MAT_NO IN('测试值') GROUP BY T1.HEAT_NO, T3.SG_GRADE_1, t1.ST_NO), mm2 as(select * from(select HEAT_NO, ELM_NAME, ELM_ACT from tqmts29 where HEAT_NO = '测试值') PIVOT(SUM(ELM_ACT) FOR ELM_NAME IN('C' C, 'Si' Si, 'Mn' Mn, 'P' P, 'S' S, 'Cr' Cr, 'Ni' Ni, 'Cu' Cu, 'Al' Al, 'Mo' Mo, 'V' V, 'Ti' Ti, 'Nb' Nb, 'N' N, 'As' AA, 'Sn' Sn, 'W' W, 'H' H, 'Creq/Nieq' CRNI))) select mm1.SG_GRADE_1, mm1.MAT_WIDTH || 'x' || mm1.MAT_THICK MAT_THICK, mm1.ST_NO, MM1.MAT_WT, round(MM1.MAT_LEN / 1000, 3) MAT_LEN, MM1.SLAB_NO, MM1.HEAT_NO, C, SI, MN, P, S, CR, NI, CU, AL, MO, V, TI, NB, N, AA, SN, W, H, CRNI from mm1 left join mm2 on mm1.HEAT_NO = mm2.HEAT_NO;

