SELECT A.CODE DEP_NAME, C.BREAKDN_DATE, C.REMARK REMARK_BFR, B.REMARK, CASE WHEN B.BREAKDN_DATE IS NULL THEN DATEDIFF(DAY, TO_DATE(C.BREAKDN_DATE,'YYYYMMDD'), TO_DATE('20250101','YYYYMMDD') - 1) ELSE 0 END OPERATE_CYCLE, CASE WHEN C.TOTAL_OPERATE_CYCLE IS NULL OR CASE WHEN B.REMARK IS NULL THEN DATEDIFF(DAY, TO_DATE(C.BREAKDN_DATE,'YYYYMMDD'), TO_DATE('20250101','YYYYMMDD') - 1) ELSE B.TOTAL_OPERATE_CYCLE END IS NULL THEN NULL ELSE GREATEST(C.TOTAL_OPERATE_CYCLE, CASE WHEN B.REMARK IS NULL THEN DATEDIFF(DAY, TO_DATE(C.BREAKDN_DATE,'YYYYMMDD'), TO_DATE('20250101','YYYYMMDD') - 1) ELSE B.TOTAL_OPERATE_CYCLE END) END TOTAL_OPERATE_CYCLE FROM TEP0002 A LEFT JOIN TFOSMT02A B ON A.CODE = B.DEP_NAME AND B.BREAKDN_DATE = TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYYMMDD') LEFT JOIN (SELECT DEP_NAME, REMARK, BREAKDN_DATE, TOTAL_OPERATE_CYCLE FROM TFOSMT02A WHERE (DEP_NAME, BREAKDN_DATE) IN (SELECT DEP_NAME, MAX(BREAKDN_DATE) FROM TFOSMT02A WHERE BREAKDN_DATE < TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYYMMDD') GROUP BY DEP_NAME) ) C ON A.CODE = C.DEP_NAME LEFT JOIN TFOSMT02B D ON A.CODE = D.DEP_NAME WHERE A.CODE_CLASS = 'FOSMT1' AND A.CODE_DESC_2_CONTENT != ' ' ORDER BY A.CODE_DESC_2_CONTENT;

