SELECT SUM(PLAN_CHARGE_1) PLAN_CHARGE_1, SUM(PLAN_CHARGE_2) PLAN_CHARGE_2, SUM(PRODUCT_CHARGE_1) PRODUCT_CHARGE_1, SUM(PRODUCT_CHARGE_2) PRODUCT_CHARGE_2, SUM(SLAB_WT_1) SLAB_WT_1, SUM(SLAB_WT_2) SLAB_WT_2, SUM(CC_REMAIN_NUM_1) CC_REMAIN_NUM_1, SUM(CC_REMAIN_NUM_2) CC_REMAIN_NUM_2, SUM(TOTAL_SLAB_WT) TOTAL_SLAB_WT, SUM(PLAN_PROD_DAY) PLAN_PROD_DAY, SUM(REAL_PRODUCT_DAY) REAL_PRODUCT_DAY, DECODE(SUM(PRODUCT_CHARGE_1), 0, 0, ROUND(100.0 * SUM(CC_REMAIN_NUM_1) / SUM(PRODUCT_CHARGE_1),1)) CC_REMAIN_RATE_1, DECODE(SUM(PRODUCT_CHARGE_2), 0, 0, ROUND(100.0 * SUM(CC_REMAIN_NUM_2) / SUM(PRODUCT_CHARGE_2),1)) CC_REMAIN_RATE_2, 1.000 * SUM(SLAB_WT_2) / SUM(TOTAL_SLAB_WT) PRODUCT_RATE, MAX(TIME_PROGRESS) TIME_PROGRESS, DECODE(MAX(CAST(B1.REMARK AS INTEGER) + CAST(B2.REMARK AS INTEGER)), 0, 0, SUM(TOTAL_SLAB_WT) / MAX(CAST(B1.REMARK AS INTEGER) + CAST(B2.REMARK AS INTEGER)) * 100) PROD_PROGRESS, DECODE(MAX(CAST(B1.REMARK AS INTEGER)), 0, 0, SUM(SLAB_WT_1) / MAX(CAST(B1.REMARK AS INTEGER)) * 100) PROD_PROGRESS_1, DECODE(MAX(CAST(B2.REMARK AS INTEGER)), 0, 0, SUM(SLAB_WT_2) / MAX(CAST(B2.REMARK AS INTEGER)) * 100) PROD_PROGRESS_2, MAX(B1.REMARK) PLAN_SLAB_WT_1, MAX(B2.REMARK) PLAN_SLAB_WT_2, MAX(CAST(B1.REMARK AS INTEGER) + CAST(B2.REMARK AS INTEGER)) PLAN_SLAB_WT, '合计' DATE_TIME FROM TFOSMT03A A LEFT JOIN TFOSMT96B B1 ON B1.DATE_TIME = SUBSTR(TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1, 'YYYYMMDD'), 1, 6) AND B1.ITEM_ENAME = 'FOSMT03-107' LEFT JOIN TFOSMT96B B2 ON B2.DATE_TIME = SUBSTR(TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1, 'YYYYMMDD'), 1, 6) AND B2.ITEM_ENAME = 'FOSMT03-108' WHERE 1 = 1 AND A.DATE_TIME < '20250101' AND A.DATE_TIME >= SUBSTR(TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1, 'YYYYMMDD'), 1, 6) || '01';

