日合计' SHIFT_GROUP, '当日合计' CC_MACH_NO, SUM(PRODUCT_CHARGE), SUM(QUALIFIED_CHARGE), 100 * CAST(ROUND(DECODE(SUM(PRODUCT_CHARGE),0,0,CAST(SUM(QUALIFIED_CHARGE) AS DECIMAL)/CAST(SUM(PRODUCT_CHARGE) AS DECIMAL)), 4) AS DECIMAL(5,4)) QUALIFIED_RATE, ' ' REMARK FROM T UNION ALL SELECT TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYYMMDD') DATE_TIME, '月度累计' SHIFT_GROUP, '月度累计' CC_MACH_NO, SUM(PRODUCT_CHARGE), SUM(QUALIFIED_CHARGE), 100 * CAST(ROUND(DECODE(SUM(PRODUCT_CHARGE),0,0,CAST(SUM(QUALIFIED_CHARGE) AS DECIMAL)/CAST(SUM(PRODUCT_CHARGE) AS DECIMAL)), 4) AS DECIMAL(5,4)) QUALIFIED_RATE, ' ' REMARK FROM TFOSMT05C WHERE FACTORY_DIV = 'A20' AND SUBSTR(DATE_TIME, 1, 6) = SUBSTR(TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYYMMDD'), 1, 6) ) ORDER BY SHIFT_GROUP, CC_MACH_NO;

