WITH T AS ( SELECT ITEM_CNAME, UNIT, PROC_DIV, SEQ_NO, ITEM_ENAME, SUBSTR(TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYYMMDD'), 1, 4) DATE_TIME FROM TFOSMT96A WHERE TABLE_NAME = 'FOSMT08-1' AND FACTORY_DIV = 'A10' AND PROC_DIV = 'Y' ), S AS ( SELECT ITEM_ENAME, SUM(REMARK_1) REMARK_1, SUM(REMARK_2) REMARK_2 FROM TFOSMT08A WHERE DATE_TIME >= TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYYMM') || '01' AND DATE_TIME <= TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYYMMDD') GROUP BY ITEM_ENAME ) SELECT ROW_NUMBER() OVER () SEQ_NO, T.ITEM_CNAME, T.UNIT, T.PROC_DIV, T.DATE_TIME, TO_NUMBER(COALESCE(A.REMARK,0)) INDEX_TARGET_1, TO_NUMBER(COALESCE(B.REMARK,0)) INDEX_TARGET_2, TO_NUMBER(COALESCE(C.INDEX_DAY,0)) INDEX_DAY_1, CASE WHEN T.ITEM_ENAME = 'FOSMT08-127' THEN C2.REMARK_1 ELSE DECODE(C2.REMARK_2,0,0,C2.REMARK_1 / C2.REMARK_2) END INDEX_TOL_1, TO_NUMBER(COALESCE(D.INDEX_DAY,0)) INDEX_DAY_2, CASE WHEN T.ITEM_ENAME = 'FOSMT08-127' THEN D2.REMARK_1 ELSE DECODE(D2.REMARK_2,0,0,D2.REMARK_1 / D2.REMARK_2) END INDEX_TOL_2, CASE WHEN T.ITEM_ENAME = 'FOSMT08-127' THEN C2.REMARK_1 + D2.REMARK_1 ELSE DECODE((C2.REMARK_2 + D2.REMARK_2),0,0,(C2.REMARK_1 + D2.REMARK_1) / (C2.REMARK_2 + D2.REMARK_2)) END INDEX_TOL FROM T LEFT JOIN TFOSMT96B A ON T.ITEM_CNAME = A.ITEM_CNAME AND A.FACTORY_DIV = 'A10' AND T.DATE_TIME = A.DATE_TIME LEFT JOIN TFOSMT96B B ON T.ITEM_CNAME = B.ITEM_CNAME AND B.FACTORY_DIV = 'A20' AND T.DATE_TIME = B.DATE_TIME LEFT JOIN TFOSMT08A C ON A.ITEM_ENAME = C.ITEM_ENAME AND C.DATE_TIME = TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYYMMDD') LEFT JOIN S C2 ON A.ITEM_ENAME = C2.ITEM_ENAME LEFT JOIN TFOSMT08A D ON B.ITEM_ENAME = D.ITEM_ENAME AND D.DATE_TIME = TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYYMMDD') LEFT JOIN S D2 ON B.ITEM_ENAME = D2.ITEM_ENAME ORDER BY T.SEQ_NO, T.ITEM_ENAME;

