SELECT A.ITEM_ENAME ENERGY_CODE, SUBSTR(A.ITEM_CNAME,1,LENGTH(A.ITEM_CNAME)-8) ENERGY_CNAME, B0.REMARK PRICE, A.UNIT, B1.REMARK VALUE_REAL, B2.REMARK VALUE_TARGET, COALESCE(TO_NUMBER(C1.REMARK),0) VALUE_DAY_1, COALESCE(TO_NUMBER(C2.REMARK),0) VALUE_DAY_2, COALESCE(TO_NUMBER(C3.REMARK),0) VALUE_DAY_3, CASE WHEN A.ITEM_ENAME IN ('FOSMT09-103','FOSMT09-105','FOSMT09-123') THEN ROUND(COALESCE(DECODE(D.REMARK_2,0,0,D.REMARK_1 / D.REMARK_2),0),0) WHEN A.ITEM_ENAME IN ('FOSMT09-131', 'FOSMT09-133') THEN ROUND(D.REMARK, 0) ELSE ROUND(COALESCE(DECODE(D.REMARK_2,0,0,D.REMARK_1 / D.REMARK_2),0),2) END VALUE_MONTH FROM TFOSMT96A A LEFT JOIN TFOSMT09C B0 ON A.ITEM_ENAME = B0.ITEM_ENAME LEFT JOIN TFOSMT96B B1 ON SUBSTR(A.ITEM_CNAME,1,LENGTH(A.ITEM_CNAME)-8) = SUBSTR(B1.ITEM_CNAME,1,LENGTH(B1.ITEM_CNAME)-8) AND MOD(SUBSTR(B1.ITEM_ENAME,11,1),2) = 1 AND B1.TABLE_NAME = 'FOSMT09-1' AND B1.DATE_TIME = TO_CHAR((TO_DATE('20250101','YYYYMMDD') - 1),'YYYY') LEFT JOIN TFOSMT96B B2 ON SUBSTR(A.ITEM_CNAME,1,LENGTH(A.ITEM_CNAME)-8) = SUBSTR(B2.ITEM_CNAME,1,LENGTH(B2.ITEM_CNAME)-8) AND MOD(SUBSTR(B2.ITEM_ENAME,11,1),2) = 0 AND B2.TABLE_NAME = 'FOSMT09-1' AND B2.DATE_TIME = TO_CHAR((TO_DATE('20250101','YYYYMMDD') - 1),'YYYY') LEFT JOIN TFOSMT09A C1 ON A.ITEM_ENAME = C1.ITEM_ENAME AND C1.DATE_TIME = TO_CHAR((TO_DATE('20250101','YYYYMMDD') - 3),'YYYYMMDD') LEFT JOIN TFOSMT09A C2 ON A.ITEM_ENAME = C2.ITEM_ENAME AND C2.DATE_TIME = TO_CHAR((TO_DATE('20250101','YYYYMMDD') - 2),'YYYYMMDD') LEFT JOIN TFOSMT09A C3 ON A.ITEM_ENAME = C3.ITEM_ENAME AND C3.DATE_TIME = TO_CHAR((TO_DATE('20250101','YYYYMMDD') - 1),'YYYYMMDD') LEFT JOIN (SELECT ITEM_ENAME,AVG(REMARK) AS REMARK, SUM(TO_NUMBER(REMARK_1)) REMARK_1, SUM(TO_NUMBER(REMARK_2)) REMARK_2 FROM TFOSMT09A WHERE SUBSTR(DATE_TIME,1,6) = TO_CHAR((TO_DATE('20250101','YYYYMMDD') - 1),'YYYYMM') GROUP BY ITEM_ENAME) D ON A.ITEM_ENAME = D.ITEM_ENAME WHERE MOD(SUBSTR(A.ITEM_ENAME,11,1),2) = 1 AND A.TABLE_NAME = 'FOSMT09-1' ORDER BY A.SEQ_NO;

