WITH T(LEVEL, TIME) AS (SELECT 1, TO_DATE('20250101','YYYYMMDD') - 3 FROM DUAL WHERE 1 = 1 UNION ALL SELECT LEVEL + 1,TIME + 1 FROM DUAL, T WHERE T.TIME < TO_DATE('20250101','YYYYMMDD') - 1) SELECT TO_CHAR(T.TIME,'YYYYMMDD') DATE_TIME, A.IRON_S IRON_S_1, A.IRON_P IRON_P_1, A.IRON_TEMP IRON_TEMP_1, A.MOLTIRON_WT MOLTIRON_WT_1, A.SCRAPE_SLAG_WGT SCRAPE_SLAG_WGT_1, A.RATE RATE_1, A.RATIO_NUM RATIO_NUM_1, B.IRON_S IRON_S_2, B.IRON_P IRON_P_2, B.IRON_TEMP IRON_TEMP_2, B.MOLTIRON_WT MOLTIRON_WT_2, B.SCRAPE_SLAG_WGT SCRAPE_SLAG_WGT_2, B.RATE RATE_2, B.RATIO_NUM RATIO_NUM_2 FROM T LEFT JOIN TFOSMT10A A ON TO_CHAR(T.TIME,'YYYYMMDD') = A.DATE_TIME AND A.FACTORY_DIV = 'A10' LEFT JOIN TFOSMT10A B ON TO_CHAR(T.TIME,'YYYYMMDD') = B.DATE_TIME AND B.FACTORY_DIV = 'A20' WHERE 1 = 1;

