SELECT T.DATE_TIME, AVG(A.IRON_S) IRON_S_1, AVG(A.IRON_P) IRON_P_1, AVG(A.IRON_TEMP) IRON_TEMP_1, AVG(A.MOLTIRON_WT) MOLTIRON_WT_1, AVG(A.SCRAPE_SLAG_WGT) SCRAPE_SLAG_WGT_1, AVG(A.RATE) RATE_1, AVG(A.RATIO_NUM) RATIO_NUM_1, AVG(B.IRON_S) IRON_S_2, AVG(B.IRON_P) IRON_P_2, AVG(B.IRON_TEMP) IRON_TEMP_2, AVG(B.MOLTIRON_WT) MOLTIRON_WT_2, AVG(B.SCRAPE_SLAG_WGT) SCRAPE_SLAG_WGT_2, AVG(B.RATE) RATE_2, AVG(B.RATIO_NUM) RATIO_NUM_2 FROM (SELECT '合计' DATE_TIME FROM DUAL) T LEFT JOIN TFOSMT10A A ON SUBSTR(A.DATE_TIME,1,6) = SUBSTR(TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYYMMDD'),1,6) AND A.FACTORY_DIV = 'A10' LEFT JOIN TFOSMT10A B ON SUBSTR(B.DATE_TIME,1,6) = SUBSTR(TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYYMMDD'),1,6) AND B.FACTORY_DIV = 'A20' AND A.DATE_TIME = B.DATE_TIME WHERE 1 = 1 GROUP BY T.DATE_TIME;

