WITH T(LEVEL, TIME) AS (SELECT 1, TO_DATE('20250101','YYYYMMDD') - 3 FROM DUAL WHERE 1 = 1 UNION ALL SELECT LEVEL + 1,TIME + 1 FROM DUAL, T WHERE T.TIME < TO_DATE('20250101','YYYYMMDD') - 1) SELECT A.DATE_TIME, A.RAW_IRON_WT RAW_IRON_WT_1, A.SCRAP_STEEL_IN SCRAP_STEEL_IN_1, A.SCRAP_STEEL_BOF SCRAP_STEEL_BOF_1, A.SCRAP_STEEL_HEAT SCRAP_STEEL_HEAT_1, A.RATE RATE_1, A.SCRAP_STEEL_SR SCRAP_STEEL_SR_1, B.RAW_IRON_WT RAW_IRON_WT_2, B.SCRAP_STEEL_IN SCRAP_STEEL_IN_2, B.SCRAP_STEEL_BOF SCRAP_STEEL_BOF_2, B.SCRAP_STEEL_HEAT SCRAP_STEEL_HEAT_2, B.RATE RATE_2, B.SCRAP_STEEL_SR SCRAP_STEEL_SR_2, B.SCRAP_STEEL_TPD, C.SCRAP_STEEL_TPC, C.RATIO_NUM FROM T LEFT JOIN TFOSMT10B A ON TO_CHAR(T.TIME,'YYYYMMDD') = A.DATE_TIME AND A.FACTORY_DIV = 'A10' LEFT JOIN TFOSMT10B B ON TO_CHAR(T.TIME,'YYYYMMDD') = B.DATE_TIME AND B.FACTORY_DIV = 'A20' LEFT JOIN TFOSMT10B C ON TO_CHAR(T.TIME,'YYYYMMDD') = C.DATE_TIME AND C.FACTORY_DIV = 'A00' WHERE 1 = 1;

