WITH T(LEVEL, TIME) AS (SELECT 1, TO_DATE('20250101','YYYYMMDD') - 3 FROM DUAL WHERE 1 = 1 UNION ALL SELECT LEVEL + 1,TIME + 1 FROM DUAL, T WHERE T.TIME < TO_DATE('20250101','YYYYMMDD') - 1) SELECT A.DATE_TIME, A.PRODUCT_CHARGE PRODUCT_CHARGE_1, A.QUALIFIED_CHARGE QUALIFIED_CHARGE_1, DECODE(A.PRODUCT_CHARGE,0,0, ROUND(100.00 * A.QUALIFIED_CHARGE / A.PRODUCT_CHARGE,2)) QUALIFIED_RATE_1, CASE WHEN 0 IS NULL OR A.ACT_COSTING IS NULL THEN NULL ELSE GREATEST(0, A.ACT_COSTING) END ACT_COSTING_1, B.PRODUCT_CHARGE PRODUCT_CHARGE_2, B.QUALIFIED_CHARGE QUALIFIED_CHARGE_2, DECODE(B.PRODUCT_CHARGE,0,0,ROUND(100.00 * B.QUALIFIED_CHARGE / B.PRODUCT_CHARGE,2)) QUALIFIED_RATE_2, CASE WHEN 0 IS NULL OR B.ACT_COSTING IS NULL THEN NULL ELSE GREATEST(0, B.ACT_COSTING) END ACT_COSTING_2, CASE WHEN 0 IS NULL OR A.ACT_COSTING IS NULL THEN NULL ELSE GREATEST(0, A.ACT_COSTING) END + CASE WHEN 0 IS NULL OR B.ACT_COSTING IS NULL THEN NULL ELSE GREATEST(0, B.ACT_COSTING) END ACT_COSTING_TOTAL FROM T LEFT JOIN TFOSMT10C A ON TO_CHAR(T.TIME,'YYYYMMDD') = A.DATE_TIME AND A.FACTORY_DIV = 'A10' LEFT JOIN TFOSMT10C B ON TO_CHAR(T.TIME,'YYYYMMDD') = B.DATE_TIME AND B.FACTORY_DIV = 'A20' WHERE 1 = 1;

