WITH T(LEVEL, TIME) AS (SELECT 1, TO_DATE(TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYYMM') || '01','YYYYMMDD') FROM DUAL WHERE 1 = 1 UNION ALL SELECT LEVEL + 1,TIME + 1 FROM DUAL, T WHERE T.TIME < TO_DATE('20250101','YYYYMMDD') - 1) SELECT '合计' DATE_TIME, SUM(A.PRODUCT_CHARGE) PRODUCT_CHARGE_1, SUM(A.QUALIFIED_CHARGE) QUALIFIED_CHARGE_1, ROUND(100.00 * SUM(A.QUALIFIED_CHARGE) / SUM(A.PRODUCT_CHARGE),2) QUALIFIED_RATE_1, CASE WHEN SUM(A.ACT_COSTING) < 0 THEN 0 ELSE SUM(A.ACT_COSTING) END ACT_COSTING_1, SUM(B.PRODUCT_CHARGE) PRODUCT_CHARGE_2, SUM(B.QUALIFIED_CHARGE) QUALIFIED_CHARGE_2, ROUND(100.00 * SUM(B.QUALIFIED_CHARGE) / SUM(B.PRODUCT_CHARGE),2) QUALIFIED_RATE_2, CASE WHEN SUM(B.ACT_COSTING) < 0 THEN 0 ELSE SUM(B.ACT_COSTING) END ACT_COSTING_2, CASE WHEN SUM(A.ACT_COSTING) < 0 THEN 0 ELSE SUM(A.ACT_COSTING) END + CASE WHEN SUM(B.ACT_COSTING) < 0 THEN 0 ELSE SUM(B.ACT_COSTING) END ACT_COSTING_TOTAL FROM T LEFT JOIN TFOSMT10C A ON TO_CHAR(T.TIME,'YYYYMMDD') = A.DATE_TIME AND A.FACTORY_DIV = 'A10' LEFT JOIN TFOSMT10C B ON TO_CHAR(T.TIME,'YYYYMMDD') = B.DATE_TIME AND B.FACTORY_DIV = 'A20' WHERE 1 = 1;

