SELECT A.DATE_TIME, A.ADJUST_CHARGE ADJUST_CHARGE_1, A.MOLTIRON_WT MOLTIRON_WT_1, A.REMARK REMARK_1, B.ADJUST_CHARGE ADJUST_CHARGE_2, B.MOLTIRON_WT MOLTIRON_WT_2, B.REMARK REMARK_2, A.MOLTIRON_WT + B.MOLTIRON_WT MOLTIRON_WT_TOTAL FROM TFOSMT10D A LEFT JOIN TFOSMT10D B ON A.DATE_TIME = B.DATE_TIME AND B.FACTORY_DIV = 'A20' WHERE A.FACTORY_DIV = 'A10' AND A.DATE_TIME >= TO_CHAR((TO_DATE('20250101','YYYYMMDD') - 10),'YYYYMMDD') AND A.DATE_TIME <= TO_CHAR((TO_DATE('20250101','YYYYMMDD') - 1),'YYYYMMDD');

