SELECT '合计' DATE_TIME, SUM(A.ADJUST_CHARGE) ADJUST_CHARGE_1, SUM(A.MOLTIRON_WT) MOLTIRON_WT_1, '' REMARK_1, SUM(B.ADJUST_CHARGE) ADJUST_CHARGE_2, SUM(B.MOLTIRON_WT) MOLTIRON_WT_2, '' REMARK_2, SUM(A.MOLTIRON_WT + B.MOLTIRON_WT) MOLTIRON_WT_TOTAL FROM TFOSMT10D A LEFT JOIN TFOSMT10D B ON A.DATE_TIME = B.DATE_TIME AND B.FACTORY_DIV = 'A20' WHERE A.FACTORY_DIV = 'A10' AND A.DATE_TIME >= TO_CHAR((TO_DATE('20250101','YYYYMMDD') - 1),'YYYYMM') || '01' AND A.DATE_TIME <= TO_CHAR((TO_DATE('20250101','YYYYMMDD') - 1),'YYYYMMDD');

