WITH A(LEVEL, TIME) AS (SELECT 1, TO_DATE('20250101','YYYYMMDD') - 10 FROM DUAL WHERE 1 = 1 UNION ALL SELECT LEVEL + 1,TIME + 1 FROM DUAL, A WHERE A.TIME < TO_DATE('20250101','YYYYMMDD') - 1) SELECT TO_CHAR(A.TIME,'YYYYMMDD') DATE_TIME, B1.RATE RATE_1, B2.RATE RATE_2, B3.RATE RATE_3, B4.RATE RATE_4, B5.RATE RATE_5, B6.RATE RATE_6, B7.RATE RATE_7, B8.RATE RATE_8, C1.RATE RATE_9, C2.RATE RATE_10, C3.RATE RATE_11, C4.RATE RATE_12 FROM A LEFT JOIN TFOSMT10E B1 ON TO_CHAR(A.TIME,'YYYYMMDD') = B1.DATE_TIME AND B1.FACTORY_DIV = 'A10' AND B1.MAT_CODE = '1' LEFT JOIN TFOSMT10E B2 ON TO_CHAR(A.TIME,'YYYYMMDD') = B2.DATE_TIME AND B2.FACTORY_DIV = 'A10' AND B2.MAT_CODE = '2' LEFT JOIN TFOSMT10E B3 ON TO_CHAR(A.TIME,'YYYYMMDD') = B3.DATE_TIME AND B3.FACTORY_DIV = 'A10' AND B3.MAT_CODE = '3' LEFT JOIN TFOSMT10E B4 ON TO_CHAR(A.TIME,'YYYYMMDD') = B4.DATE_TIME AND B4.FACTORY_DIV = 'A10' AND B4.MAT_CODE = '5' LEFT JOIN TFOSMT10E B5 ON TO_CHAR(A.TIME,'YYYYMMDD') = B5.DATE_TIME AND B5.FACTORY_DIV = 'A20' AND B5.MAT_CODE = '1' LEFT JOIN TFOSMT10E B6 ON TO_CHAR(A.TIME,'YYYYMMDD') = B6.DATE_TIME AND B6.FACTORY_DIV = 'A20' AND B6.MAT_CODE = '2' LEFT JOIN TFOSMT10E B7 ON TO_CHAR(A.TIME,'YYYYMMDD') = B7.DATE_TIME AND B7.FACTORY_DIV = 'A20' AND B7.MAT_CODE = '3' LEFT JOIN TFOSMT10E B8 ON TO_CHAR(A.TIME,'YYYYMMDD') = B8.DATE_TIME AND B8.FACTORY_DIV = 'A20' AND B8.MAT_CODE = '5' LEFT JOIN TFOSMT10E C1 ON TO_CHAR(A.TIME,'YYYYMMDD') = C1.DATE_TIME AND C1.FACTORY_DIV = 'A00' AND C1.MAT_CODE = '1' LEFT JOIN TFOSMT10E C2 ON TO_CHAR(A.TIME,'YYYYMMDD') = C2.DATE_TIME AND C2.FACTORY_DIV = 'A00' AND C2.MAT_CODE = '2' LEFT JOIN TFOSMT10E C3 ON TO_CHAR(A.TIME,'YYYYMMDD') = C3.DATE_TIME AND C3.FACTORY_DIV = 'A00' AND C3.MAT_CODE = '3' LEFT JOIN TFOSMT10E C4 ON TO_CHAR(A.TIME,'YYYYMMDD') = C4.DATE_TIME AND C4.FACTORY_DIV = 'A00' AND C4.MAT_CODE = '5';

