WITH A(LEVEL, TIME) AS (SELECT 1, TO_DATE(TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYYMM') || '01','YYYYMMDD') FROM DUAL WHERE 1 = 1 UNION ALL SELECT LEVEL + 1,TIME + 1 FROM DUAL, A WHERE A.TIME < TO_DATE('20250101','YYYYMMDD') - 1) SELECT '合计' DATE_TIME, ROUND(AVG(B1.RATE),2) RATE_1, ROUND(AVG(B2.RATE),2) RATE_2, ROUND(AVG(B3.RATE),2) RATE_3, ROUND(AVG(B4.RATE),2) RATE_4, ROUND(AVG(B5.RATE),2) RATE_5, ROUND(AVG(B6.RATE),2) RATE_6, ROUND(AVG(B7.RATE),2) RATE_7, ROUND(AVG(B8.RATE),2) RATE_8, ROUND(AVG(C1.RATE),2) RATE_9, ROUND(AVG(C2.RATE),2) RATE_10, ROUND(AVG(C3.RATE),2) RATE_11, ROUND(AVG(C4.RATE),2) RATE_12 FROM A LEFT JOIN TFOSMT10E B1 ON TO_CHAR(A.TIME,'YYYYMMDD') = B1.DATE_TIME AND B1.FACTORY_DIV = 'A10' AND B1.MAT_CODE = '1' LEFT JOIN TFOSMT10E B2 ON TO_CHAR(A.TIME,'YYYYMMDD') = B2.DATE_TIME AND B2.FACTORY_DIV = 'A10' AND B2.MAT_CODE = '2' LEFT JOIN TFOSMT10E B3 ON TO_CHAR(A.TIME,'YYYYMMDD') = B3.DATE_TIME AND B3.FACTORY_DIV = 'A10' AND B3.MAT_CODE = '3' LEFT JOIN TFOSMT10E B4 ON TO_CHAR(A.TIME,'YYYYMMDD') = B4.DATE_TIME AND B4.FACTORY_DIV = 'A10' AND B4.MAT_CODE = '5' LEFT JOIN TFOSMT10E B5 ON TO_CHAR(A.TIME,'YYYYMMDD') = B5.DATE_TIME AND B5.FACTORY_DIV = 'A20' AND B5.MAT_CODE = '1' LEFT JOIN TFOSMT10E B6 ON TO_CHAR(A.TIME,'YYYYMMDD') = B6.DATE_TIME AND B6.FACTORY_DIV = 'A20' AND B6.MAT_CODE = '2' LEFT JOIN TFOSMT10E B7 ON TO_CHAR(A.TIME,'YYYYMMDD') = B7.DATE_TIME AND B7.FACTORY_DIV = 'A20' AND B7.MAT_CODE = '3' LEFT JOIN TFOSMT10E B8 ON TO_CHAR(A.TIME,'YYYYMMDD') = B8.DATE_TIME AND B8.FACTORY_DIV = 'A20' AND B8.MAT_CODE = '5' LEFT JOIN TFOSMT10E C1 ON TO_CHAR(A.TIME,'YYYYMMDD') = C1.DATE_TIME AND C1.FACTORY_DIV = 'A00' AND C1.MAT_CODE = '1' LEFT JOIN TFOSMT10E C2 ON TO_CHAR(A.TIME,'YYYYMMDD') = C2.DATE_TIME AND C2.FACTORY_DIV = 'A00' AND C2.MAT_CODE = '2' LEFT JOIN TFOSMT10E C3 ON TO_CHAR(A.TIME,'YYYYMMDD') = C3.DATE_TIME AND C3.FACTORY_DIV = 'A00' AND C3.MAT_CODE = '3' LEFT JOIN TFOSMT10E C4 ON TO_CHAR(A.TIME,'YYYYMMDD') = C4.DATE_TIME AND C4.FACTORY_DIV = 'A00' AND C4.MAT_CODE = '5';

