WITH A(LEVEL, TIME) AS (SELECT 1, TO_DATE('20250101','YYYYMMDD') - 10 FROM DUAL WHERE 1 = 1 UNION ALL SELECT LEVEL + 1,TIME + 1 FROM DUAL, A WHERE A.TIME < TO_DATE('20250101','YYYYMMDD') - 1) SELECT TO_CHAR(A.TIME,'YYYYMMDD') DATE_TIME, B1.PRODUCT_CHARGE PRODUCT_CHARGE_1, B1.SMELT_CHARGE SMELT_CHARGE_L1, B1.RATE RATE_L1, B1.RATIO_NUM RATIO_NUM_L1, B1.TOTAL_DURATION TOTAL_DURATION_L1, B2.SMELT_CHARGE SMELT_CHARGE_R1, B2.RATE RATE_R1, B3.PRODUCT_CHARGE PRODUCT_CHARGE_2, B3.SMELT_CHARGE SMELT_CHARGE_L2, B3.RATE RATE_L2, B3.RATIO_NUM RATIO_NUM_L2, B3.TOTAL_DURATION TOTAL_DURATION_L2, B4.SMELT_CHARGE SMELT_CHARGE_R2, B4.RATE RATE_R2 FROM A LEFT JOIN TFOSMT10F B1 ON TO_CHAR(A.TIME,'YYYYMMDD') = B1.DATE_TIME AND B1.FACTORY_DIV = 'A10' AND B1.STATION_ID = 'L' LEFT JOIN TFOSMT10F B2 ON TO_CHAR(A.TIME,'YYYYMMDD') = B2.DATE_TIME AND B2.FACTORY_DIV = 'A10' AND B2.STATION_ID = 'R' LEFT JOIN TFOSMT10F B3 ON TO_CHAR(A.TIME,'YYYYMMDD') = B3.DATE_TIME AND B3.FACTORY_DIV = 'A20' AND B3.STATION_ID = 'L' LEFT JOIN TFOSMT10F B4 ON TO_CHAR(A.TIME,'YYYYMMDD') = B4.DATE_TIME AND B4.FACTORY_DIV = 'A20' AND B4.STATION_ID = 'R';

