WITH A(LEVEL, TIME) AS (SELECT 1, TO_DATE(TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYYMM') || '01','YYYYMMDD') FROM DUAL WHERE 1 = 1 UNION ALL SELECT LEVEL + 1,TIME + 1 FROM DUAL, A WHERE A.TIME < TO_DATE('20250101','YYYYMMDD') - 1) SELECT '合计' DATE_TIME, SUM(B1.PRODUCT_CHARGE) PRODUCT_CHARGE_1, SUM(B1.SMELT_CHARGE) SMELT_CHARGE_L1, ROUND(100.0 * SUM(B1.SMELT_CHARGE) / SUM(B1.PRODUCT_CHARGE),2) RATE_L1, ROUND(100.0 * SUM(0.01 * B1.RATIO_NUM * B1.PRODUCT_CHARGE) / SUM(B1.PRODUCT_CHARGE),2) RATIO_NUM_L1, ROUND(AVG(B1.TOTAL_DURATION),1) TOTAL_DURATION_L1, SUM(B2.SMELT_CHARGE) SMELT_CHARGE_R1, ROUND(100.0 * SUM(B2.SMELT_CHARGE) / SUM(B2.PRODUCT_CHARGE),2) RATE_R1, SUM(B3.PRODUCT_CHARGE) PRODUCT_CHARGE_2, SUM(B3.SMELT_CHARGE) SMELT_CHARGE_L2, ROUND(100.0 * SUM(B3.SMELT_CHARGE) / SUM(B3.PRODUCT_CHARGE),2) RATE_L2, ROUND(100.0 * SUM(0.01 * B3.RATIO_NUM * B3.PRODUCT_CHARGE) / SUM(B3.PRODUCT_CHARGE),2) RATIO_NUM_L2, ROUND(AVG(B3.TOTAL_DURATION),1) TOTAL_DURATION_L2, SUM(B4.SMELT_CHARGE) SMELT_CHARGE_R2, ROUND(100.0 * SUM(B4.SMELT_CHARGE) / SUM(B4.PRODUCT_CHARGE),2) RATE_R2 FROM A LEFT JOIN TFOSMT10F B1 ON TO_CHAR(A.TIME,'YYYYMMDD') = B1.DATE_TIME AND B1.FACTORY_DIV = 'A10' AND B1.STATION_ID = 'L' LEFT JOIN TFOSMT10F B2 ON TO_CHAR(A.TIME,'YYYYMMDD') = B2.DATE_TIME AND B2.FACTORY_DIV = 'A10' AND B2.STATION_ID = 'R' LEFT JOIN TFOSMT10F B3 ON TO_CHAR(A.TIME,'YYYYMMDD') = B3.DATE_TIME AND B3.FACTORY_DIV = 'A20' AND B3.STATION_ID = 'L' LEFT JOIN TFOSMT10F B4 ON TO_CHAR(A.TIME,'YYYYMMDD') = B4.DATE_TIME AND B4.FACTORY_DIV = 'A20' AND B4.STATION_ID = 'R';

