WITH T(LEVEL, TIME) AS (SELECT 1, TO_DATE('20250101','YYYYMMDD') - 3 FROM DUAL WHERE 1 = 1 UNION ALL SELECT LEVEL + 1,TIME + 1 FROM DUAL, T WHERE T.TIME < TO_DATE('20250101','YYYYMMDD') - 1) SELECT TO_CHAR(T.TIME,'YYYYMMDD') DATE_TIME, '' AAA, SLAB_WT, TO_CHAR(CAST(MOLTIRON_WT AS DECIMAL(10,0))) MOLTIRON_WT, TO_CHAR(CAST(SCRAP_STEEL_TPC AS DECIMAL(10,0))) SCRAP_STEEL_TPC, MAT_WT, STOCK_TOTAL_WT, TO_CHAR(IRON_STEEL_RATE1) IRON_STEEL_RATE1, IRON_STEEL_RATE2, TO_CHAR(DAYS) AS DAYS, RATE_FINISH_DAY FROM T LEFT JOIN TFOSMT10G A ON A.DATE_TIME = TO_CHAR(T.TIME,'YYYYMMDD') WHERE 1 = 1;

