-- sql_id: CHANGE-59 | module: WMSM | 类型: 查询
-- 文件: Server/WMSM/p_wmsm_8170/wmfm01_inq.cpp | ledger_anchor: L3944-L3954 | 实际语句行: L3944-L3954
SELECT '月度合计' DATE_TIME, '' AAA, SLAB_WT, TO_CHAR(CAST(MOLTIRON_WT AS DECIMAL(10,0))) MOLTIRON_WT, TO_CHAR(CAST(SCRAP_STEEL_TPC AS DECIMAL(10,0))) SCRAP_STEEL_TPC, MAT_WT, STOCK_TOTAL_WT, TO_CHAR(IRON_STEEL_RATE1) IRON_STEEL_RATE1, IRON_STEEL_RATE2, TO_CHAR(A.DAYS) AS DAYS, RATE_FINISH_DAY FROM TFOSMT10H A WHERE DATE_TIME = TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYYMMDD');

