SELECT '年度累计（万吨）' DATE_TIME, '' AAA, ROUND(A.SLAB_WT / 10000,2) + TO_NUMBER(B.REMARK) SLAB_WT, TO_CHAR(CAST(ROUND(A.MOLTIRON_WT / 10000,2) + TO_NUMBER(C.REMARK) AS DECIMAL(10,2))) MOLTIRON_WT, TO_CHAR(CAST(ROUND(A.SCRAP_STEEL_TPC / 10000,2) + TO_NUMBER(D.REMARK) AS DECIMAL(10,2))) SCRAP_STEEL_TPC, ROUND(A.MAT_WT / 10000,2) + TO_NUMBER(E.REMARK) MAT_WT, ROUND(A.STOCK_TOTAL_WT / 10000,2) + TO_NUMBER(F.REMARK) STOCK_TOTAL_WT, TO_CHAR(CAST(ROUND(1.0000 * (ROUND(A.SLAB_WT / 10000,2) + TO_NUMBER(B.REMARK)) / (ROUND(A.MAT_WT / 10000,2) + TO_NUMBER(E.REMARK)),4) AS DECIMAL(5,4))) IRON_STEEL_RATE1, CAST(ROUND(1.0000 * ROUND(T.MOLTIRON_WT1 / 10000,2) / (ROUND(A.STOCK_TOTAL_WT / 10000,2) + TO_NUMBER(F.REMARK)),4) AS DECIMAL(5,4)) IRON_STEEL_RATE2, TO_CHAR(A.DAYS) AS DAYS, A.RATE_FINISH_DAY FROM TFOSMT10H A LEFT JOIN TFOSMT96B B ON B.ITEM_ENAME = 'FOSMT10-603' AND B.DATE_TIME = TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYYMM') LEFT JOIN TFOSMT96B C ON C.ITEM_ENAME = 'FOSMT10-604' AND C.DATE_TIME = TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYYMM') LEFT JOIN TFOSMT96B D ON D.ITEM_ENAME = 'FOSMT10-605' AND D.DATE_TIME = TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYYMM') LEFT JOIN TFOSMT96B E ON E.ITEM_ENAME = 'FOSMT10-606' AND E.DATE_TIME = TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYYMM') LEFT JOIN TFOSMT96B F ON F.ITEM_ENAME = 'FOSMT10-607' AND F.DATE_TIME = TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYYMM') LEFT JOIN (SELECT SUM(MOLTIRON_WT1) MOLTIRON_WT1 FROM TFOSMT10G WHERE DATE_TIME < '20250101' AND DATE_TIME >= TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYY') || '0101') T ON 1 = 1 WHERE A.DATE_TIME = TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYYMMDD');

-- ---------------------------------------------------------------------
-- sql_id: CHANGE-61 | module: WMSM | 类型: 查询
