SELECT DATE_TIME,AAA,SLAB_WT,MOLTIRON_WT,SCRAP_STEEL_TPC,STOCK_TOTAL_WT,IRON_STEEL_RATE1,IRON_STEEL_RATE2,T.DAYS,RATE_FINISH_DAY FROM (SELECT '1' RN, '年产进度' DATE_TIME, '' AAA, 0 SLAB_WT, '' MOLTIRON_WT, '' SCRAP_STEEL_TPC, 0 STOCK_TOTAL_WT, '比月度目标' IRON_STEEL_RATE1, 0 IRON_STEEL_RATE2, '比年产目标' AS DAYS, 0 RATE_FINISH_DAY FROM (SELECT * FROM DUAL) UNION ALL SELECT '2','铁厂','钢厂',0,'','',0,'',0,'',0 FROM DUAL UNION ALL SELECT '3',B1.REMARK,B2.REMARK,0,'','',0,'',0,'',0 FROM DUAL LEFT JOIN TFOSMT96B B1 ON B1.ITEM_ENAME = 'FOSMT10-601' AND B1.DATE_TIME = TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYY') LEFT JOIN TFOSMT96B B2 ON B2.ITEM_ENAME = 'FOSMT10-602' AND B2.DATE_TIME = TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1,'YYYY') ) T ORDER BY RN;

