-- sql_id: CHANGE-64 | module: WMSM | 类型: 查询
-- 文件: Server/WMSM/p_wmsm_8170/wmfm01_inq.cpp | ledger_anchor: L4365-L4423 | 实际语句行: L4365-L4423
SELECT A.CODE, A2.CODE FACTORY_DIV, A.CODE_DESC_1_CONTENT ITEM_CNAME, COALESCE(C.UNIT_COST, 0) REMARK, COALESCE(B1.UNIT_COST, 0) REMARK_1, COALESCE(B2.UNIT_COST, 0) REMARK_2, COALESCE(B3.UNIT_COST, 0) REMARK_3, COALESCE(B4.UNIT_COST, 0) REMARK_4, COALESCE(B5.UNIT_COST, 0) REMARK_5, COALESCE(B6.UNIT_COST, 0) REMARK_6, COALESCE(B7.UNIT_COST, 0) REMARK_7, COALESCE(ROUND(D.REMARK_MON, 2), 0) REMARK_MON, COALESCE(ROUND(E.REMARK_YEAR, 2), 0) REMARK_YEAR FROM TEP0002 A LEFT JOIN TEP0002 A2 ON A2.CODE_CLASS = 'FOSMT5' AND A2.CODE = 'A00' LEFT JOIN TFOSMT10J B1 ON A.CODE = B1.ITEM_ENAME AND B1.FACTORY_DIV = A2.CODE AND B1.DATE_TIME = TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 7, 'YYYYMMDD') LEFT JOIN TFOSMT10J B2 ON A.CODE = B2.ITEM_ENAME AND B2.FACTORY_DIV = A2.CODE AND B2.DATE_TIME = TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 6, 'YYYYMMDD') LEFT JOIN TFOSMT10J B3 ON A.CODE = B3.ITEM_ENAME AND B3.FACTORY_DIV = A2.CODE AND B3.DATE_TIME = TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 5, 'YYYYMMDD') LEFT JOIN TFOSMT10J B4 ON A.CODE = B4.ITEM_ENAME AND B4.FACTORY_DIV = A2.CODE AND B4.DATE_TIME = TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 4, 'YYYYMMDD') LEFT JOIN TFOSMT10J B5 ON A.CODE = B5.ITEM_ENAME AND B5.FACTORY_DIV = A2.CODE AND B5.DATE_TIME = TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 3, 'YYYYMMDD') LEFT JOIN TFOSMT10J B6 ON A.CODE = B6.ITEM_ENAME AND B6.FACTORY_DIV = A2.CODE AND B6.DATE_TIME = TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 2, 'YYYYMMDD') LEFT JOIN TFOSMT10J B7 ON A.CODE = B7.ITEM_ENAME AND B7.FACTORY_DIV = A2.CODE AND B7.DATE_TIME = TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1, 'YYYYMMDD') LEFT JOIN TFOSMT10J C ON A.CODE = C.ITEM_ENAME AND C.FACTORY_DIV = A2.CODE AND C.DATE_TIME = TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1, 'YYYYMM') LEFT JOIN ( SELECT ITEM_ENAME, FACTORY_DIV, SUM(TO_NUMBER(REMARK1)), SUM(TO_NUMBER(REMARK2)), CASE WHEN ITEM_ENAME = '06' THEN DECODE(SUM(TO_NUMBER(REMARK2)), 0, 0, SUM(TO_NUMBER(REMARK1)) / SUM(TO_NUMBER(REMARK2))) - DECODE(SUM(TO_NUMBER(REMARK4)), 0, 0, SUM(TO_NUMBER(REMARK3)) / SUM(TO_NUMBER(REMARK4))) - DECODE(SUM(TO_NUMBER(REMARK6)), 0, 0, SUM(TO_NUMBER(REMARK5)) / SUM(TO_NUMBER(REMARK6))) WHEN ITEM_ENAME = '01' THEN DECODE(SUM(TO_NUMBER(REMARK2)), 0, 0, SUM(TO_NUMBER(REMARK1)) / SUM(TO_NUMBER(REMARK2))) - DECODE(SUM(TO_NUMBER(REMARK4)), 0, 0, SUM(TO_NUMBER(REMARK3)) / SUM(TO_NUMBER(REMARK4))) ELSE DECODE(SUM(TO_NUMBER(REMARK2)), 0, 0, SUM(TO_NUMBER(REMARK1)) / SUM(TO_NUMBER(REMARK2))) END REMARK_MON FROM TFOSMT10J WHERE DATE_TIME <= TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1, 'YYYYMMDD') AND DATE_TIME >= TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1, 'YYYYMM') || '01' AND LENGTH(DATE_TIME) = 8 GROUP BY ITEM_ENAME, FACTORY_DIV ) D ON A.CODE = D.ITEM_ENAME AND D.FACTORY_DIV = A2.CODE LEFT JOIN ( SELECT ITEM_ENAME, FACTORY_DIV, SUM(TO_NUMBER(REMARK1)), SUM(TO_NUMBER(REMARK2)), CASE WHEN ITEM_ENAME = '06' THEN DECODE(SUM(TO_NUMBER(REMARK2)), 0, 0, SUM(TO_NUMBER(REMARK1)) / SUM(TO_NUMBER(REMARK2))) - DECODE(SUM(TO_NUMBER(REMARK4)), 0, 0, SUM(TO_NUMBER(REMARK3)) / SUM(TO_NUMBER(REMARK4))) - DECODE(SUM(TO_NUMBER(REMARK6)), 0, 0, SUM(TO_NUMBER(REMARK5)) / SUM(TO_NUMBER(REMARK6))) WHEN ITEM_ENAME = '01' THEN DECODE(SUM(TO_NUMBER(REMARK2)), 0, 0, SUM(TO_NUMBER(REMARK1)) / SUM(TO_NUMBER(REMARK2))) - DECODE(SUM(TO_NUMBER(REMARK4)), 0, 0, SUM(TO_NUMBER(REMARK3)) / SUM(TO_NUMBER(REMARK4))) ELSE DECODE(SUM(TO_NUMBER(REMARK2)), 0, 0, SUM(TO_NUMBER(REMARK1)) / SUM(TO_NUMBER(REMARK2))) END REMARK_YEAR FROM TFOSMT10J WHERE DATE_TIME <= TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1, 'YYYYMMDD') AND DATE_TIME >= TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1, 'YYYY') || '0101' AND LENGTH(DATE_TIME) = 8 GROUP BY ITEM_ENAME, FACTORY_DIV ) E ON A.CODE = E.ITEM_ENAME AND E.FACTORY_DIV = A2.CODE WHERE A.CODE_CLASS = 'FOSMTD' AND A.CODE = '06' AND A2.CODE = 'A00' ORDER BY A2.CODE, A.CODE_DESC_2_CONTENT, A.CODE;

