SELECT FACTORY_DIV, STATION_ID STATION_NAME, REMARK_7 STATION_NO_1, REMARK_1 STATION_NO_2, REMARK_2 STATION_NO_3, REMARK_3 STATION_NO_4, REMARK_4 STATION_NO_5, REMARK_5 STATION_NO_6, REMARK_6 STATION_NO_7, REMARK_8 PERIOD_TIME, REMARK FROM TFOSMT11A WHERE DATE_TIME = TO_CHAR(TO_DATE('20250101','YYYYMMDD') - 1 - DAYOFWEEK(TO_DATE('20250101','YYYYMMDD') - 1) + 1, 'YYYYMMDD') ORDER BY FACTORY_DIV, STATION_ID;

