-- sql_id: CHANGE-99 | module: WMSM | 类型: 查询
-- 文件: Server/WMSM/p_wmsm_8180/wmsmpcgz_inq.cpp | ledger_anchor: L86-L95 | 实际语句行: L86-L95
SELECT DISTINCT(ST_NO) FROM( SELECT a.*, B.CC_SEQ, B.SG_SIGN, B.CAST_LOT_NO, B.CAST_LOT_DIV_NO, B.CAST_LOT_SUM, B.REFINE_DIV, B.PLAN_POUR_WT, B.NEW_TEST_NO, B.PLAN_DATE , B.CC_PREP_TIME, B.POUR_TIME, B.CC_REQ_TIME_FLAG, B.HOT_SEND_FLAG, B.HOT_CHARGE_FLAG, B.CARRY_DIV, B.SLAB_DEST, B.BILLET_TYPE, B.SLAB_THICK , B.SLAB_WIDTH, B.SLAB_LEN, B.SHIFT_NO, B.SHIFT_GROUP, B.C_DIV, B.CC_REQ_TIMEL4, B.CAST_LOT_NO2, B.CAST_LOT_DIV_NO2 , B.CAST_LOT_SUM2, C.START_TIME_REAL FROM TPSSM11 A, TPSSM10 B, TPSSM12 C WHERE a.FACTORY_DIV = 'LG1' and a.factory_div = b.factory_div and a.pono = b.pono AND a.SM_PLAN_NO = c.SM_PLAN_NO AND c.AREA_ID = 3 AND((c.START_TIME_REAL >= TO_CHAR(SYSDATE - 6.0/24, 'YYYYMMDDHH24MISS') AND c.START_TIME_REAL <= TO_CHAR(SYSDATE + 1, 'YYYYMMDDHH24MISS') OR c.START_TIME_REAL = ' ') OR a.RUN_STATUS < '53') order by c.START_TIME_REAL);

