SELECT PONO, A FROM ( SELECT MIN(START_TIME) A, PONO FROM ( SELECT CASE WHEN TRIM(START_TIME_REAL) IS NULL THEN START_TIME ELSE START_TIME_REAL END START_TIME, PONO FROM TPSSM12 WHERE FACTORY_DIV = TRIM('测试值') AND AREA_ID = 3 ) GROUP BY PONO ) ORDER BY A ASC;

