-- sql_id: CHANGE-127 | module: PSSM | 类型: 查询
-- 文件: Server/PSSM/p_pssm_13050/pssm14f2_inq.cpp | ledger_anchor: L108-L128 | 实际语句行: L108-L128
SELECT A.CC_MACH_NO, A.CAST_NO, A.CAST_PONO_SUM, B.CAST_LOT_NO, MAX(B.SLAB_DEST) SLAB_DEST, CASE WHEN MAX(C.CC_MACH_NO) IS NULL THEN ' ' ELSE '浇注中' END CUR_POUR, COUNT(A.SM_PLAN_NO) CAST_PONO_SUM, MAX(B1.LOT_NUM) LOT_NUM, (LISTAGG(DISTINCT A.ST_NO,'*') WITHIN GROUP (ORDER BY A.ST_NO)) ST_NO, (LISTAGG(DISTINCT B.SG_SIGN,'*') WITHIN GROUP (ORDER BY B.SG_SIGN)) SG_SIGN, A.CC_MACH_NO FROM TPSSM11 A LEFT JOIN TPSSM26 C ON A.CAST_NO = C.CAST_NO AND A.CAST_DIV_NO = C.CAST_DIV_NO AND A.RUN_STATUS = '52' LEFT JOIN TPSSM01 B ON A.PONO = B.PONO LEFT JOIN (SELECT CAST_LOT_NO, CC_MACH_NO, COUNT(PONO) LOT_NUM FROM TPSSM10 GROUP BY CC_MACH_NO, CAST_LOT_NO )B1 ON B.CAST_LOT_NO = B1.CAST_LOT_NO AND B1.CC_MACH_NO = A.CC_MACH_NO WHERE 1 = 1 AND A.RUN_STATUS < '53' AND A.CAST_NO IN (SELECT CAST_NO FROM TPSSM11 WHERE PONO_STATUS >= 20);

