-- sql_id: CHANGE-132 | module: PSSM | 类型: 查询
-- 文件: Server/PSSM/p_pssm_13060/mmlgap05_inq.cpp | ledger_anchor: L105-L134 | 实际语句行: L105-L134
SELECT T1.STATION_NO,nvl(WT_YEAR,0) as WT_YEAR,nvl(WT_MONTH,0) as WT_MONTH,nvl(WT_WEEK,0) as WT_WEEK,nvl(WT_DAY,0) as WT_DAY FROM(select STATION_NO, sum(OUT_STEEL_WT) AS WT_YEAR FROM(select case BLOW_START_TIME1 WHEN to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(BLOW_START_TIME1, 1, 8) when to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(BLOW_START_TIME1, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS BLOW_START_TIME1, OUT_STEEL_WT, case STATION_NO WHEN STATION_NO = 5 THEN '5#转炉钢水' when STATION_NO = 6 THEN '6#转炉钢水' when STATION_NO = 7 THEN '7#转炉钢水' end as STATION_NO from TMMSM21 where FACTORY_DIV = 'A2') where BLOW_START_TIME1 like '2025' || '%' GROUP BY STATION_NO) T1 LEFT JOIN(select STATION_NO, sum(OUT_STEEL_WT) AS WT_MONTH FROM (select case BLOW_START_TIME1 WHEN to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(BLOW_START_TIME1, 1, 8)when to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING( BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(BLOW_START_TIME1, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS BLOW_START_TIME1, OUT_STEEL_WT, case STATION_NO WHEN STATION_NO = 5 THEN '5#转炉钢水' when STATION_NO = 6 THEN '6#转炉钢水' when STATION_NO = 7 THEN '7#转炉钢水' end as STATION_NO from TMMSM21 where FACTORY_DIV = 'A2') where BLOW_START_TIME1 like '202501' || '%' GROUP BY STATION_NO)T2 ON T1.STATION_NO = T2.STATION_NO LEFT JOIN(select STATION_NO, sum(OUT_STEEL_WT) AS WT_WEEK FROM(select case BLOW_START_TIME1 WHEN to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(BLOW_START_TIME1, 1, 8)when to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING( BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS')THEN to_char(to_date(SUBSTRING(BLOW_START_TIME1, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS BLOW_START_TIME1, OUT_STEEL_WT, case STATION_NO WHEN STATION_NO = 5 THEN '5#转炉钢水' when STATION_NO = 6 THEN '6#转炉钢水' when STATION_NO = 7 THEN '7#转炉钢水' end as STATION_NO from TMMSM21 where FACTORY_DIV = 'A2') where WEEK_ISO(to_date('20250101', 'YYYY-MM-DD')) = WEEK_ISO(to_date(BLOW_START_TIME1, 'YYYY-MM-DD')) GROUP BY STATION_NO)T3 ON T1.STATION_NO = T3.STATION_NO LEFT JOIN (select STATION_NO, sum(OUT_STEEL_WT) AS WT_DAY FROM(select case BLOW_START_TIME1 WHEN to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS') < to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(BLOW_START_TIME1, 1, 8) when to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(BLOW_START_TIME1, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS BLOW_START_TIME1, OUT_STEEL_WT, case STATION_NO WHEN STATION_NO = 5 THEN '5#转炉钢水' when STATION_NO = 6 THEN '6#转炉钢水' when STATION_NO = 7 THEN '7#转炉钢水' end as STATION_NO from TMMSM21 where FACTORY_DIV = 'A2') where BLOW_START_TIME1 = '20250101' GROUP BY STATION_NO) T4 ON T1.STATION_NO = T4.STATION_NO;

-- ---------------------------------------------------------------------
-- sql_id: CHANGE-133 | module: PSSM | 类型: 查询
-- 文件: Server/PSSM/p_pssm_13060/mmlgap05_inq.cpp | ledger_anchor: L171-L200 | 实际语句行: L171-L200
SELECT T1.STATION_NO,nvl(WT_YEAR,0) as WT_YEAR,nvl(WT_MONTH,0) as WT_MONTH,nvl(WT_WEEK,0) as WT_WEEK,nvl(WT_DAY,0) as WT_DAY FROM(select STATION_NO, sum(FIN_LADLE_W_L) AS WT_YEAR FROM(select case START_TIME WHEN to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(START_TIME, 1, 8) when to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(START_TIME, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS START_TIME, FIN_LADLE_W_L, case STATION_NO WHEN STATION_NO = 3 THEN '3#LF产量' when STATION_NO = 4 THEN '4#LF产量' end as STATION_NO from TMMSM24 where FACTORY_DIV = 'A2' and START_TIME not in('')) where START_TIME like '2025' || '%' GROUP BY STATION_NO) T1 LEFT JOIN(select STATION_NO, sum(FIN_LADLE_W_L) AS WT_MONTH FROM (select case START_TIME WHEN to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(START_TIME, 1, 8)when to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING( START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(START_TIME, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS START_TIME, FIN_LADLE_W_L, case STATION_NO WHEN STATION_NO = 3 THEN '3#LF产量' when STATION_NO = 4 THEN '4#LF产量' end as STATION_NO from TMMSM24 where FACTORY_DIV = 'A2' and START_TIME not in('')) where START_TIME like '202501' || '%' GROUP BY STATION_NO)T2 ON T1.STATION_NO = T2.STATION_NO LEFT JOIN(select STATION_NO, sum(FIN_LADLE_W_L) AS WT_WEEK FROM(select case START_TIME WHEN to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(START_TIME, 1, 8)when to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING( START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS')THEN to_char(to_date(SUBSTRING(START_TIME, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS START_TIME, FIN_LADLE_W_L, case STATION_NO WHEN STATION_NO = 3 THEN '3#LF产量' when STATION_NO = 4 THEN '4#LF产量' end as STATION_NO from TMMSM24 where FACTORY_DIV = 'A2' and START_TIME not in('')) where WEEK_ISO(to_date('20250101', 'YYYY-MM-DD')) = WEEK_ISO(to_date(START_TIME, 'YYYY-MM-DD')) GROUP BY STATION_NO)T3 ON T1.STATION_NO = T3.STATION_NO LEFT JOIN (select STATION_NO, sum(FIN_LADLE_W_L) AS WT_DAY FROM(select case START_TIME WHEN to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') < to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(START_TIME, 1, 8) when to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(START_TIME, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS START_TIME, FIN_LADLE_W_L, case STATION_NO WHEN STATION_NO = 3 THEN '3#LF产量' when STATION_NO = 4 THEN '4#LF产量' end as STATION_NO from TMMSM24 where FACTORY_DIV = 'A2' and START_TIME not in('')) where START_TIME = '20250101' GROUP BY STATION_NO) T4 ON T1.STATION_NO = T4.STATION_NO;

-- ---------------------------------------------------------------------
-- sql_id: CHANGE-134 | module: PSSM | 类型: 查询
-- 文件: Server/PSSM/p_pssm_13060/mmlgap05_inq.cpp | ledger_anchor: L241-L274 | 实际语句行: L241-L274
SELECT T1.STATION_NO,nvl(WT_YEAR,0) as WT_YEAR,nvl(WT_MONTH,0) as WT_MONTH,nvl(WT_WEEK,0) as WT_WEEK,nvl(WT_DAY,0) as WT_DAY FROM(select STATION_NO, sum(SLAB_WT) AS WT_YEAR FROM(select case slab_cut_time WHEN to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(slab_cut_time, 1, 8) when to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING(slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(slab_cut_time, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS slab_cut_time, SLAB_WT, case STATION_NO WHEN STATION_NO = 5 THEN '5#连铸机板坯' WHEN STATION_NO = 6 THEN '6#连铸机板坯' WHEN STATION_NO = 7 THEN '7#连铸机板坯' end as STATION_NO from (select a.SLAB_WT, a.STATION_NO, a.slab_cut_time from TMMSM33 a where a.FACTORY_DIV = 'A2')) where slab_cut_time like '2025' || '%' GROUP BY STATION_NO) T1 LEFT JOIN(select STATION_NO, sum(SLAB_WT) AS WT_MONTH FROM (select case slab_cut_time WHEN to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(slab_cut_time, 1, 8) when to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING(slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(slab_cut_time, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS slab_cut_time, SLAB_WT, case STATION_NO WHEN STATION_NO = 5 THEN '5#连铸机板坯' WHEN STATION_NO = 6 THEN '6#连铸机板坯' WHEN STATION_NO = 7 THEN '7#连铸机板坯' end as STATION_NO from (select a.SLAB_WT, a.STATION_NO, a.slab_cut_time from TMMSM33 a where a.FACTORY_DIV = 'A2')) where slab_cut_time like '202501' || '%' GROUP BY STATION_NO)T2 ON T1.STATION_NO = T2.STATION_NO LEFT JOIN(select STATION_NO, sum(SLAB_WT) AS WT_WEEK FROM(select case slab_cut_time WHEN to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING (slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT( SUBSTRING(slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(slab_cut_time, 1, 8) when to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING(slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date( SUBSTRING(slab_cut_time, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS slab_cut_time, SLAB_WT, case STATION_NO WHEN STATION_NO = 5 THEN '5#连铸机板坯' WHEN STATION_NO = 6 THEN '6#连铸机板坯' WHEN STATION_NO = 7 THEN '7#连铸机板坯' end as STATION_NO from(select a.SLAB_WT, a.STATION_NO, a.slab_cut_time from TMMSM33 a where a.FACTORY_DIV = 'A2')) where WEEK_ISO(to_date('20250101', 'YYYY-MM-DD')) = WEEK_ISO(to_date(slab_cut_time, 'YYYY-MM-DD')) GROUP BY STATION_NO)T3 ON T1.STATION_NO = T3.STATION_NO LEFT JOIN(select STATION_NO, sum(SLAB_WT) AS WT_DAY FROM(select case slab_cut_time WHEN to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(slab_cut_time, 1, 8) when to_date(slab_cut_time, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING(slab_cut_time, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(slab_cut_time, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS slab_cut_time, SLAB_WT, case STATION_NO WHEN STATION_NO = 5 THEN '5#连铸机板坯' WHEN STATION_NO = 6 THEN '6#连铸机板坯' WHEN STATION_NO = 7 THEN '7#连铸机板坯' end as STATION_NO from(select a.SLAB_WT, a.STATION_NO, a.slab_cut_time from TMMSM33 a where a.FACTORY_DIV = 'A2')) where slab_cut_time = '20250101' GROUP BY STATION_NO) T4 ON T1.STATION_NO = T4.STATION_NO;

