-- sql_id: CHANGE-382 | module: PSSM | 类型: 查询
-- 文件: Server/PSSM/p_pssm_13060/pssmap03_bof_inq.cpp | ledger_anchor: L103-L129 | 实际语句行: L103-L129
select PROD_WT_BOF,PROD_WT_B1,PROD_WT_B2,PROD_WT_B3,PROD_WT_LF,PROD_WT_RH,WORK_TIME_BOF,TIME_PRE_BOF,STEEL_NET_WT, METAL_WT, BOF_NUM, PROD_WT_PRE FROM(select cast(sum(b.slab_wt) as decimal(20, 3)) as PROD_WT_BOF from tmmsm21 a, tmmsm33 b where a.heat_no = b.heat_no and a.BLOW_START_TIME1 <> ' ' and TO_CHAR((to_date(a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') >= '20250101' and TO_CHAR((to_date(a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') < '20250101' and a.FACTORY_DIV = 'A1'), (select cast(sum(b.slab_wt) as decimal(20, 3)) as PROD_WT_B1 from tmmsm21 a, tmmsm33 b where a.heat_no = b.heat_no and a.BLOW_START_TIME1 <> ' ' and TO_CHAR((to_date( a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') >= '20250101' and TO_CHAR((to_date(a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') < '20250101' and a.FACTORY_DIV = 'A1' and substr(a.heat_no, 3, 1) = '1'), (select cast(sum(b.slab_wt) as decimal(20, 3)) as PROD_WT_B2 from tmmsm21 a, tmmsm33 b where a.heat_no = b.heat_no and a.BLOW_START_TIME1 <> ' ' and TO_CHAR((to_date(a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') >= '20250101' and TO_CHAR((to_date(a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') < '20250101' and a.FACTORY_DIV = 'A1' and substr(a.heat_no, 3, 1) = '2'), (select cast(sum(b.slab_wt) as decimal(20, 3)) as PROD_WT_B3 from tmmsm21 a, tmmsm33 b where a.heat_no = b.heat_no and a.BLOW_START_TIME1 <> ' ' and TO_CHAR((to_date(a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') >= '20250101' and TO_CHAR((to_date(a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') < '20250101' and a.FACTORY_DIV = 'A1' and substr(a.heat_no, 3, 1) = '3'), (select cast(sum(b.slab_wt) as decimal(20, 3)) as PROD_WT_LF from tmmsm21 a, tmmsm33 b, tmmsm24 c where a.heat_no = b.heat_no and a.heat_no = c.heat_no and a.BLOW_START_TIME1 <> ' ' and TO_CHAR((to_date(a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') >= '20250101' and TO_CHAR((to_date(a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') < '20250101' and a.FACTORY_DIV = 'A1'), (select cast(sum(b.slab_wt) as decimal(20, 3)) as PROD_WT_RH from tmmsm21 a, tmmsm33 b, tmmsm23 c where a.heat_no = b.heat_no and a.heat_no = c.heat_no and a.BLOW_START_TIME1 <> ' ' and TO_CHAR((to_date(a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') >= '20250101' and TO_CHAR((to_date(a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') < '20250101' and a.FACTORY_DIV = 'A1'), (select cast(sum(a.SMELT_CYCLE) / 3600 as decimal(20, 3)) as WORK_TIME_BOF, cast(sum(a.SMELT_CYCLE) / (count(a.heat_no) * 60) as decimal(20, 3)) as TIME_PRE_BOF, cast(sum(a.OUT_STEEL_WT) as decimal(20, 3)) as STEEL_NET_WT, cast( sum(a.MOLTIRON_WT) + sum(a.SCRAP_WEIGHT) + sum(a.scrap_wt) as decimal(20, 3)) as METAL_WT, count(a.heat_no) as BOF_NUM, cast( sum(a.OUT_STEEL_WT) / count(a.heat_no) as decimal(20, 3)) as PROD_WT_PRE from tmmsm21 a where a.BLOW_START_TIME1 <> ' ' and TO_CHAR((to_date(a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') >= '20250101' and TO_CHAR( (to_date(a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') < '20250101' and a.FACTORY_DIV = 'A1');

-- ---------------------------------------------------------------------
-- sql_id: CHANGE-383 | module: PSSM | 类型: 查询
-- 文件: Server/PSSM/p_pssm_13060/pssmap03_cc_inq.cpp | ledger_anchor: L95-L113 | 实际语句行: L95-L113
SELECT PROD_WT_CC,HEAT_NUM_CC,STEEL_WT_CC,PROD_WT_C1,PROD_WT_C2,PROD_WT_C3 FROM(select cast(sum(b.slab_wt) as decimal(20, 3)) AS PROD_WT_CC, count(distinct(a.heat_no)) AS HEAT_NUM_CC from tmmsm21 a, tmmsm33 b where a.heat_no = b.heat_no and a.BLOW_START_TIME1 <> ' ' and TO_CHAR((to_date(a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') >= '20250101' and TO_CHAR((to_date(a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') < '20250101' and a.FACTORY_DIV = 'A1'), (select cast(sum(b.CAST_STEEL_WT) as decimal(20, 3)) AS STEEL_WT_CC from tmmsm21 a, tmmsm31 b where a.heat_no = b.heat_no and a.BLOW_START_TIME1 <> ' ' and TO_CHAR(( to_date(a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') >= '20250101' and TO_CHAR((to_date( a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') < '20250101' and a.FACTORY_DIV = 'A1'), (select cast(sum(b.slab_wt) as decimal(20, 3)) AS PROD_WT_C1 from tmmsm21 a, tmmsm33 b where a.heat_no = b.heat_no and a.BLOW_START_TIME1 <> ' ' and TO_CHAR((to_date(a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') >= '20250101' and TO_CHAR((to_date(a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') < '20250101' and a.FACTORY_DIV = 'A1' and substr(b.cast_no, 2, 1) = '1'), (select cast(sum(b.slab_wt) as decimal(20, 3)) AS PROD_WT_C2 from tmmsm21 a, tmmsm33 b where a.heat_no = b.heat_no and a.BLOW_START_TIME1 <> ' ' and TO_CHAR(( to_date(a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') >= '20250101' and TO_CHAR((to_date( a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') < '20250101' and a.FACTORY_DIV = 'A1' and substr(b.cast_no, 2, 1) = '2'), (select cast(sum(b.slab_wt) as decimal(20, 3)) AS PROD_WT_C3 from tmmsm21 a, tmmsm33 b where a.heat_no = b.heat_no and a.BLOW_START_TIME1 <> ' ' and TO_CHAR((to_date(a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') >= '20250101' and TO_CHAR((to_date(a.BLOW_START_TIME1, 'YYYYMMDDHH24MISS') + 3.0/24), 'YYYYMMDD') < '20250101' and a.FACTORY_DIV = 'A1' and substr(b.cast_no, 2, 1) = '3');
